package com.packcheck;

public enum HotkeyAction
{
	OPEN_PANEL,
	SELECT_DEFAULT_PACK
}

package com.packcheck;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup(PackCheckConfig.GROUP)
public interface PackCheckConfig extends Config
{
	String GROUP = "packcheck";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show checklist overlay",
		description = "Show a compact, non-interactive PackCheck summary overlay",
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hotkey",
		name = "PackCheck hotkey",
		description = "Controls only the PackCheck panel or selected checklist",
		position = 1
	)
	default Keybind hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "hotkeyAction",
		name = "Hotkey action",
		description = "Open the panel or select the profile's default pack",
		position = 2
	)
	default HotkeyAction hotkeyAction()
	{
		return HotkeyAction.OPEN_PANEL;
	}

	@ConfigItem(
		keyName = "selectDefaultOnLogin",
		name = "Default pack on login",
		description = "Select the default pack stored for the current local profile after login",
		position = 3
	)
	default boolean selectDefaultOnLogin()
	{
		return false;
	}

	@ConfigItem(
		keyName = "notifyAfterBank",
		name = "Notify after bank closes",
		description = "Notify once when leaving the bank with an incomplete selected pack",
		position = 4
	)
	default boolean notifyAfterBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyWhenReady",
		name = "Notify when ready",
		description = "Notify when the selected pack changes from incomplete to ready",
		position = 5
	)
	default boolean notifyWhenReady()
	{
		return false;
	}

	@ConfigItem(
		keyName = "notifyWhenInvalid",
		name = "Notify when invalid",
		description = "Notify when a previously ready pack becomes incomplete",
		position = 6
	)
	default boolean notifyWhenInvalid()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeOptionalWarnings",
		name = "Include optional warnings",
		description = "Include optional-item warnings in notification text",
		position = 7
	)
	default boolean includeOptionalWarnings()
	{
		return false;
	}

	@ConfigItem(
		keyName = "notificationSound",
		name = "Notification sound",
		description = "Use RuneLite's configured notification sound",
		position = 8
	)
	default boolean notificationSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notificationCooldownSeconds",
		name = "Notification cooldown",
		description = "Minimum seconds between PackCheck notifications",
		position = 9
	)
	default int notificationCooldownSeconds()
	{
		return 8;
	}
}

package com.packcheck;

import com.packcheck.model.PackEvaluation;
import com.packcheck.model.RequirementResult;
import com.packcheck.model.RequirementStatus;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.ColorScheme;

public class PackCheckOverlay extends OverlayPanel
{
	private static final Color READY = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color MISSING = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color WARNING = ColorScheme.PROGRESS_INPROGRESS_COLOR;
	private final PackCheckConfig config;
	private volatile PackEvaluation evaluation = PackEvaluation.NONE;

	@Inject
	public PackCheckOverlay(PackCheckConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPreferredSize(new Dimension(220, 0));
	}

	public void setEvaluation(PackEvaluation evaluation)
	{
		this.evaluation = evaluation;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || evaluation.packName.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("PackCheck - " + evaluation.packName)
			.color(evaluation.ready ? READY : evaluation.requiredMachineFailureCount() == 0 ? WARNING : MISSING)
			.build());
		boolean manualOnly = !evaluation.ready && evaluation.requiredMachineFailureCount() == 0;
		panelComponent.getChildren().add(LineComponent.builder()
			.left(evaluation.ready ? "[OK] Ready" : manualOnly ? "[?] Check details" : "[X] Not ready")
			.right(evaluation.requiredFailureCount() + (manualOnly ? " check" : " missing"))
			.leftColor(evaluation.ready ? READY : manualOnly ? WARNING : MISSING)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Pack " + evaluation.satisfiedInventoryChecks() + "/" + evaluation.totalInventoryChecks()
				+ "  Wear " + evaluation.satisfiedEquipmentChecks() + "/" + evaluation.totalEquipmentChecks())
			.right("Check " + evaluation.satisfiedManualChecks() + "/" + evaluation.totalManualChecks())
			.leftColor(Color.LIGHT_GRAY)
			.build());
		int shown = 0;
		for (RequirementResult result : evaluation.results)
		{
			if (!result.isRequiredFailure())
			{
				continue;
			}
			boolean manual = result.status == RequirementStatus.MANUAL_CHECK;
			panelComponent.getChildren().add(LineComponent.builder()
				.left((manual ? "[?] " : "[X] ") + result.resolvedRequirement.requirement.displayName)
				.right(manual ? "check" : result.actual + "/" + result.expected)
				.leftColor(manual ? WARNING : MISSING)
				.build());
			if (++shown >= 4)
			{
				break;
			}
		}
		if (evaluation.warningCount() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("[!] Optional warnings")
				.right(Long.toString(evaluation.warningCount()))
				.leftColor(WARNING)
				.build());
		}
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Use PackCheck hotkey for sidebar")
			.leftColor(Color.LIGHT_GRAY)
			.build());
		return super.render(graphics);
	}
}

package com.packcheck;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.packcheck.model.ImportPreview;
import com.packcheck.model.Pack;
import com.packcheck.model.PackComposition;
import com.packcheck.model.PackEvaluation;
import com.packcheck.model.PackResolution;
import com.packcheck.model.PackSnapshot;
import com.packcheck.model.PackStore;
import com.packcheck.model.PackType;
import com.packcheck.model.PresetSummary;
import com.packcheck.service.BuiltInPresetService;
import com.packcheck.service.CaptureService;
import com.packcheck.service.ChargeService;
import com.packcheck.service.DoseService;
import com.packcheck.service.ItemFamilyService;
import com.packcheck.service.NotificationCoordinator;
import com.packcheck.service.PackEvaluator;
import com.packcheck.service.PackRepository;
import com.packcheck.service.PackResolver;
import com.packcheck.service.SnapshotService;
import com.packcheck.ui.PackCheckController;
import com.packcheck.ui.PackCheckPanel;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "PackCheck",
	description = "Check your inventory pack, equipped gear kit, and manual trip details before leaving the bank",
	tags = {"inventory", "equipment", "loadout", "checklist", "gear", "bank", "pvm", "slayer", "raid"}
)
public class PackCheckPlugin extends Plugin implements PackCheckController
{
	/** Fast enough to feel immediate while coalescing multi-slot bank and equipment updates. */
	private static final int CHANGE_DEBOUNCE_MILLIS = 150;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PackCheckOverlay overlay;

	@Inject
	private PackCheckConfig config;

	@Inject
	private KeyManager keyManager;

	@Inject
	private Notifier notifier;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executorService;

	@Inject
	private SnapshotService snapshotService;

	private PackRepository repository;
	private PackResolver resolver;
	private PackEvaluator evaluator;
	private CaptureService captureService;
	private BuiltInPresetService presetService;
	private NotificationCoordinator notifications;
	private PackStore store = new PackStore();
	private PackSnapshot latestSnapshot = PackSnapshot.EMPTY;
	private PackCheckPanel panel;
	private NavigationButton navigationButton;
	private HotkeyListener hotkeyListener;
	private Timer debounceTimer;
	private volatile boolean bankOpen;
	private volatile String requestedProfileKey = "default";

	@Override
	protected void startUp()
	{
		String initialProfileKey = profileKey();
		DoseService doseService = new DoseService();
		ChargeService chargeService = new ChargeService();
		ItemFamilyService itemFamilyService = new ItemFamilyService(doseService, chargeService);
		repository = new PackRepository(gson);
		resolver = new PackResolver();
		evaluator = new PackEvaluator(itemFamilyService, doseService, chargeService);
		captureService = new CaptureService(doseService, chargeService);
		presetService = new BuiltInPresetService();
		notifications = new NotificationCoordinator(notifier, config);
		overlayManager.add(overlay);

		hotkeyListener = new HotkeyListener(() -> config.hotkey())
		{
			@Override
			public void hotkeyPressed()
			{
				SwingUtilities.invokeLater(() ->
				{
					if (config.hotkeyAction() == HotkeyAction.SELECT_DEFAULT_PACK && store.defaultPackId != null)
					{
						selectPack(store.defaultPackId);
					}
					else if (navigationButton != null)
					{
						clientToolbar.openPanel(navigationButton);
					}
				});
			}
		};
		keyManager.registerKeyListener(hotkeyListener);

		SwingUtilities.invokeLater(() ->
		{
			panel = new PackCheckPanel(this);
			navigationButton = NavigationButton.builder()
				.tooltip("PackCheck")
				.icon(createIcon())
				.priority(3)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navigationButton);
			debounceTimer = new Timer(CHANGE_DEBOUNCE_MILLIS, event -> evaluateCurrent(false));
			debounceTimer.setRepeats(false);
			loadProfileAsync(initialProfileKey);
		});
	}

	@Override
	protected void shutDown()
	{
		if (hotkeyListener != null)
		{
			keyManager.unregisterKeyListener(hotkeyListener);
		}
		overlayManager.remove(overlay);
		SwingUtilities.invokeLater(() ->
		{
			if (debounceTimer != null)
			{
				debounceTimer.stop();
			}
			if (navigationButton != null)
			{
				clientToolbar.removeNavigation(navigationButton);
			}
		});
		latestSnapshot = PackSnapshot.EMPTY;
		overlay.setEvaluation(PackEvaluation.NONE);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			String profileKey = profileKey();
			loadProfileAsync(profileKey);
			captureSnapshotAndSchedule(false);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			latestSnapshot = snapshotService.capture();
			SwingUtilities.invokeLater(() ->
			{
				if (debounceTimer != null)
				{
					debounceTimer.restart();
				}
			});
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			bankOpen = false;
			captureSnapshotAndSchedule(true);
		}
	}

	@Override
	public void savePack(Pack pack)
	{
		PackStore candidate = cloneStore(store);
		int existingIndex = -1;
		for (int index = 0; index < candidate.packs.size(); index++)
		{
			if (candidate.packs.get(index).id.equals(pack.id))
			{
				existingIndex = index;
				break;
			}
		}
		if (existingIndex >= 0)
		{
			candidate.packs.set(existingIndex, pack.copy());
		}
		else
		{
			candidate.packs.add(pack.copy());
		}
		if (pack.type == PackType.EQUIPMENT && Objects.equals(candidate.composition.mainPackId, pack.id))
		{
			candidate.composition.mainPackId = null;
			candidate.composition.equipmentPackId = pack.id;
		}
		else if (pack.type != PackType.EQUIPMENT && Objects.equals(candidate.composition.equipmentPackId, pack.id))
		{
			candidate.composition.equipmentPackId = null;
			candidate.composition.mainPackId = pack.id;
		}
		if (pack.type == PackType.EQUIPMENT && candidate.composition.equipmentPackId == null)
		{
			candidate.composition.equipmentPackId = pack.id;
		}
		else if (pack.type != PackType.EQUIPMENT && candidate.composition.mainPackId == null)
		{
			candidate.composition.mainPackId = pack.id;
		}
		if (pack.type == PackType.EQUIPMENT)
		{
			candidate.composition.addOnPackIds.remove(pack.id);
		}
		candidate.composition.confirmedManualRequirementIds.clear();
		try
		{
			resolver.validateNoCycles(candidate.packs);
			store = candidate;
			notifications.reset();
			persistAsync();
			evaluateCurrent(false);
		}
		catch (IllegalArgumentException exception)
		{
			showError("Pack was not saved", exception);
		}
	}

	@Override
	public void capturePack(String name)
	{
		capturePack(name, PackType.TRIP);
	}

	@Override
	public void capturePack(String name, PackType type)
	{
		clientThread.invokeLater(() ->
		{
			PackSnapshot snapshot = snapshotService.capture();
			Pack captured = captureService.capture(name, snapshot, type);
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.reviewCapturedPack(captured);
				}
			});
		});
	}

	@Override
	public void selectPack(String packId)
	{
		if (store.packs.stream().noneMatch(pack -> pack.id.equals(packId) && pack.type != PackType.EQUIPMENT))
		{
			return;
		}
		store.composition.mainPackId = packId;
		store.composition.addOnPackIds.remove(packId);
		store.composition.conflictResolutions.clear();
		store.composition.confirmedManualRequirementIds.clear();
		notifications.reset();
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void selectEquipmentPack(String packId)
	{
		if (packId != null && store.packs.stream().noneMatch(pack -> pack.id.equals(packId)
			&& pack.type == PackType.EQUIPMENT))
		{
			return;
		}
		store.composition.equipmentPackId = packId;
		store.composition.addOnPackIds.remove(packId);
		store.composition.conflictResolutions.clear();
		store.composition.confirmedManualRequirementIds.clear();
		notifications.reset();
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void setManualCheck(String requirementId, boolean confirmed)
	{
		if (confirmed)
		{
			store.composition.confirmedManualRequirementIds.add(requirementId);
		}
		else
		{
			store.composition.confirmedManualRequirementIds.remove(requirementId);
		}
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void setAddOns(List<String> addOnIds)
	{
		List<String> accepted = new ArrayList<>();
		for (String id : addOnIds)
		{
			store.packs.stream().filter(pack -> pack.id.equals(id) && pack.addOnEligible
				&& pack.type != PackType.EQUIPMENT && !pack.id.equals(store.composition.mainPackId))
				.findFirst().ifPresent(pack -> accepted.add(pack.id));
		}
		store.composition.addOnPackIds = accepted;
		store.composition.conflictResolutions.clear();
		store.composition.confirmedManualRequirementIds.clear();
		notifications.reset();
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void resolveConflict(String requirementId, String supplierPackId)
	{
		store.composition.conflictResolutions.put(requirementId, supplierPackId);
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void duplicatePack(String packId)
	{
		store.packs.stream().filter(pack -> pack.id.equals(packId)).findFirst().ifPresent(pack ->
		{
			Pack copy = pack.copyWithNewIds();
			store.packs.add(copy);
			if (copy.type == PackType.EQUIPMENT)
			{
				store.composition.equipmentPackId = copy.id;
			}
			else
			{
				store.composition.mainPackId = copy.id;
			}
			store.composition.addOnPackIds.clear();
			store.composition.conflictResolutions.clear();
			store.composition.confirmedManualRequirementIds.clear();
			persistAsync();
			evaluateCurrent(false);
		});
	}

	@Override
	public void deletePack(String packId)
	{
		boolean referenced = store.packs.stream().anyMatch(pack -> Objects.equals(pack.basePackId, packId));
		if (referenced)
		{
			showError("Pack was not deleted", new IllegalArgumentException(
				"Another pack inherits from it. Change that pack's base first."));
			return;
		}
		store.packs.removeIf(pack -> pack.id.equals(packId));
		store.composition.addOnPackIds.remove(packId);
		if (Objects.equals(store.composition.equipmentPackId, packId))
		{
			store.composition.equipmentPackId = null;
		}
		if (Objects.equals(store.composition.mainPackId, packId))
		{
			store.composition.mainPackId = store.packs.stream().filter(pack -> pack.type != PackType.EQUIPMENT)
				.map(pack -> pack.id).findFirst().orElse(null);
		}
		if (Objects.equals(store.defaultPackId, packId))
		{
			store.defaultPackId = null;
		}
		store.composition.conflictResolutions.clear();
		store.composition.confirmedManualRequirementIds.clear();
		notifications.reset();
		persistAsync();
		evaluateCurrent(false);
	}

	@Override
	public void setDefaultPack(String packId)
	{
		store.defaultPackId = packId;
		persistAsync();
		JOptionPane.showMessageDialog(panel, "Default pack saved for this local profile.", "PackCheck",
			JOptionPane.INFORMATION_MESSAGE);
	}

	@Override
	public List<PresetSummary> availablePresets()
	{
		return presetService.summaries();
	}

	@Override
	public void installPreset(String presetKey)
	{
		for (Pack existing : store.packs)
		{
			if (Objects.equals(existing.presetKey, presetKey))
			{
				selectPack(existing.id);
				JOptionPane.showMessageDialog(panel,
					"That preset is already installed. Its customized copy was selected.",
					"PackCheck presets", JOptionPane.INFORMATION_MESSAGE);
				return;
			}
		}
		try
		{
			Pack installed = presetService.create(presetKey);
			store.packs.add(installed);
			store.composition.mainPackId = installed.id;
			store.composition.addOnPackIds.clear();
			store.composition.conflictResolutions.clear();
			store.composition.confirmedManualRequirementIds.clear();
			notifications.reset();
			persistAsync();
			evaluateCurrent(false);
		}
		catch (IllegalArgumentException exception)
		{
			showError("Preset was not installed", exception);
		}
	}

	@Override
	public void resetPreset(String packId)
	{
		for (int index = 0; index < store.packs.size(); index++)
		{
			Pack current = store.packs.get(index);
			if (!current.id.equals(packId))
			{
				continue;
			}
			try
			{
				store.packs.set(index, presetService.reset(current));
				store.composition.conflictResolutions.clear();
				store.composition.confirmedManualRequirementIds.clear();
				notifications.reset();
				persistAsync();
				evaluateCurrent(false);
			}
			catch (IllegalArgumentException exception)
			{
				showError("Preset was not reset", exception);
			}
			return;
		}
	}

	@Override
	public String presetChangeSummary(String packId)
	{
		Pack current = store.packs.stream().filter(pack -> pack.id.equals(packId)).findFirst().orElse(null);
		if (current == null || current.presetKey == null || !presetService.supports(current.presetKey))
		{
			return "No built-in default is available.";
		}
		Pack latest = presetService.create(current.presetKey);
		Map<String, com.packcheck.model.PackRequirement> currentById = new LinkedHashMap<>();
		for (com.packcheck.model.PackRequirement requirement : current.requirements)
		{
			currentById.put(requirement.id, requirement);
		}
		int added = 0;
		int changed = 0;
		for (com.packcheck.model.PackRequirement requirement : latest.requirements)
		{
			com.packcheck.model.PackRequirement previous = currentById.remove(requirement.id);
			if (previous == null)
			{
				added++;
			}
			else if (!gson.toJson(previous).equals(gson.toJson(requirement)))
			{
				changed++;
			}
		}
		int removed = currentById.size();
		return "Built-in v" + current.presetVersion + " -> v" + latest.presetVersion
			+ "\nRequirements: " + added + " added, " + changed + " changed, " + removed + " removed"
			+ "\n28 slots: " + current.recommendedInventorySlots + "/" + current.switchInventorySlots + "/"
			+ current.lootInventorySlots + " -> " + latest.recommendedInventorySlots + "/"
			+ latest.switchInventorySlots + "/" + latest.lootInventorySlots
			+ " (checked / switch / loot-flex)";
	}

	@Override
	public String exportData(boolean encoded)
	{
		return encoded ? repository.exportEncoded(store) : repository.exportJson(store);
	}

	@Override
	public ImportPreview previewImport(String input)
	{
		return repository.previewImport(input, store);
	}

	@Override
	public void applyImport(ImportPreview preview, boolean replace)
	{
		try
		{
			PackStore imported = repository.merge(store, preview, replace);
			resolver.validateNoCycles(imported.packs);
			store = imported;
			persistAsync();
			evaluateCurrent(false);
		}
		catch (IllegalArgumentException exception)
		{
			showError("Import was not applied", exception);
		}
	}

	private void captureSnapshotAndSchedule(boolean afterBank)
	{
		clientThread.invokeLater(() ->
		{
			latestSnapshot = snapshotService.capture();
			SwingUtilities.invokeLater(() -> evaluateCurrent(afterBank));
		});
	}

	private void evaluateCurrent(boolean afterBank)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> evaluateCurrent(afterBank));
			return;
		}
		try
		{
			PackResolution resolution = resolver.resolve(store.composition, store.packs);
			PackEvaluation evaluation = evaluator.evaluate(resolution, latestSnapshot,
				store.composition.confirmedManualRequirementIds);
			overlay.setEvaluation(evaluation);
			if (panel != null)
			{
				panel.refresh(store, resolution, evaluation);
			}
			if (!bankOpen || afterBank)
			{
				notifications.onEvaluation(evaluation, afterBank, System.currentTimeMillis());
			}
		}
		catch (IllegalArgumentException exception)
		{
			overlay.setEvaluation(PackEvaluation.NONE);
			showError("Pack composition could not be resolved", exception);
		}
	}

	private void persistAsync()
	{
		PackStore snapshot = cloneStore(store);
		executorService.execute(() ->
		{
			try
			{
				repository.save(snapshot);
			}
			catch (IOException exception)
			{
				SwingUtilities.invokeLater(() -> showError("Pack data could not be saved", exception));
			}
		});
	}

	private void loadProfileAsync(String profileKey)
	{
		requestedProfileKey = profileKey;
		executorService.execute(() ->
		{
			try
			{
				PackStore loaded = repository.load(profileKey);
				SwingUtilities.invokeLater(() ->
				{
					if (!requestedProfileKey.equals(profileKey))
					{
						return;
					}
					store = loaded;
					if (config.selectDefaultOnLogin() && store.defaultPackId != null
						&& store.packs.stream().anyMatch(pack -> pack.id.equals(store.defaultPackId)))
					{
						store.composition.mainPackId = store.defaultPackId;
						store.composition.addOnPackIds.clear();
						store.composition.conflictResolutions.clear();
						store.composition.confirmedManualRequirementIds.clear();
					}
					notifications.reset();
					evaluateCurrent(false);
				});
			}
			catch (IOException exception)
			{
				SwingUtilities.invokeLater(() -> showError("Pack data could not be loaded", exception));
			}
		});
	}

	private String profileKey()
	{
		long accountHash = client.getAccountHash();
		return accountHash == -1L ? "default" : "account-" + Long.toUnsignedString(accountHash);
	}

	private PackStore cloneStore(PackStore source)
	{
		return gson.fromJson(gson.toJson(source), PackStore.class);
	}

	private void showError(String title, Exception exception)
	{
		JOptionPane.showMessageDialog(panel, exception.getMessage(), title, JOptionPane.ERROR_MESSAGE);
	}

	private BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(ColorScheme.DARKER_GRAY_COLOR);
		graphics.fillRoundRect(1, 1, 14, 14, 3, 3);
		graphics.setColor(ColorScheme.BRAND_ORANGE);
		graphics.setStroke(new BasicStroke(1.1f));
		graphics.drawRoundRect(1, 1, 13, 13, 3, 3);
		graphics.drawRect(4, 4, 3, 3);
		graphics.drawRect(9, 4, 3, 3);
		graphics.drawRect(4, 9, 3, 3);
		graphics.setColor(new Color(255, 222, 160));
		graphics.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.drawLine(9, 11, 10, 12);
		graphics.drawLine(10, 12, 13, 8);
		graphics.dispose();
		return image;
	}

	@Provides
	PackCheckConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(PackCheckConfig.class);
	}
}

