	public String presetKey;
	public int presetVersion;
	public String presetMethod = "";
	public String presetPlanNotes = "";
	public String presetSourceUrl = "";
	public String presetReviewedOn = "";
	public int recommendedInventorySlots;
	public int switchInventorySlots;
	public int lootInventorySlots;
	public int flexibleInventorySlots;
	public String basePackId;
	public boolean addOnEligible;
	public ExtraItemMode extraItemMode = ExtraItemMode.IGNORE;
	public List<PackRequirement> requirements = new ArrayList<>();
	public List<PackContextRule> contextRules = new ArrayList<>();

	public Pack copyWithNewIds()
	{
		Pack copy = new Pack();
		copy.name = name + " copy";
		copy.type = type;
		copy.presetKey = null;
		copy.presetVersion = 0;
		copy.presetMethod = presetMethod;
		copy.presetPlanNotes = presetPlanNotes;
		copy.presetSourceUrl = presetSourceUrl;
		copy.presetReviewedOn = presetReviewedOn;
		copy.recommendedInventorySlots = recommendedInventorySlots;
		copy.switchInventorySlots = switchInventorySlots;
		copy.lootInventorySlots = lootInventorySlots;
		copy.flexibleInventorySlots = flexibleInventorySlots;
		copy.basePackId = basePackId;
		copy.addOnEligible = addOnEligible;
		copy.extraItemMode = extraItemMode;
		for (PackRequirement requirement : requirements)
		{
			PackRequirement requirementCopy = requirement.copy();
			requirementCopy.id = UUID.randomUUID().toString();
			copy.requirements.add(requirementCopy);
		}
		return copy;
	}

	public Pack copy()
	{
		Pack copy = new Pack();
		copy.id = id;
		copy.name = name;
		copy.type = type;
		copy.presetKey = presetKey;
		copy.presetVersion = presetVersion;
		copy.presetMethod = presetMethod;
		copy.presetPlanNotes = presetPlanNotes;
		copy.presetSourceUrl = presetSourceUrl;
		copy.presetReviewedOn = presetReviewedOn;
		copy.recommendedInventorySlots = recommendedInventorySlots;
		copy.switchInventorySlots = switchInventorySlots;
		copy.lootInventorySlots = lootInventorySlots;
		copy.flexibleInventorySlots = flexibleInventorySlots;
		copy.basePackId = basePackId;
		copy.addOnEligible = addOnEligible;
		copy.extraItemMode = extraItemMode;
		for (PackRequirement requirement : requirements)
		{
			copy.requirements.add(requirement.copy());
		}
		for (PackContextRule contextRule : contextRules)
		{
			PackContextRule ruleCopy = new PackContextRule();
			ruleCopy.id = contextRule.id;
			ruleCopy.type = contextRule.type;
			ruleCopy.value = contextRule.value;
			ruleCopy.enabled = contextRule.enabled;
			ruleCopy.dismissed = contextRule.dismissed;
			copy.contextRules.add(ruleCopy);
		}
		return copy;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

