package com.packcheck.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PackEvaluation
{
	public static final PackEvaluation NONE = new PackEvaluation("", Collections.emptyList(), Collections.emptyList(), true);

	public final String packName;
	public final List<RequirementResult> results;
	public final List<RequirementResult> extras;
	public final boolean ready;

	public PackEvaluation(String packName, List<RequirementResult> results, List<RequirementResult> extras, boolean ready)
	{
		this.packName = packName;
		this.results = Collections.unmodifiableList(new ArrayList<>(results));
		this.extras = Collections.unmodifiableList(new ArrayList<>(extras));
		this.ready = ready;
	}

	public long requiredFailureCount()
	{
		return results.stream().filter(RequirementResult::isRequiredFailure).count()
			+ extras.stream().filter(RequirementResult::isRequiredFailure).count();
	}

	public long requiredManualCheckCount()
	{
		return results.stream().filter(RequirementResult::isRequiredFailure)
			.filter(result -> result.status == RequirementStatus.MANUAL_CHECK).count();
	}

	public long requiredMachineFailureCount()
	{
		return requiredFailureCount() - requiredManualCheckCount();
	}

	public long warningCount()
	{
		return results.stream().filter(result -> !result.resolvedRequirement.requirement.required
			&& result.status != RequirementStatus.SATISFIED && result.status != RequirementStatus.IGNORED).count()
			+ extras.stream().filter(result -> !result.isRequiredFailure()).count();
	}

	public long totalInventoryChecks()
	{
		return results.stream().filter(this::isInventoryCheck).count();
	}

	public long satisfiedInventoryChecks()
	{
		return results.stream().filter(this::isInventoryCheck).filter(this::isSatisfied).count();
	}

	public long totalEquipmentChecks()
	{
		return results.stream().filter(this::isEquipmentCheck).count();
	}

	public long satisfiedEquipmentChecks()
	{
		return results.stream().filter(this::isEquipmentCheck).filter(this::isSatisfied).count();
	}

	public long totalManualChecks()
	{
		return results.stream().filter(this::isManualCheck).count();
	}

	public long satisfiedManualChecks()
	{
		return results.stream().filter(this::isManualCheck).filter(this::isSatisfied).count();
	}

	private boolean isInventoryCheck(RequirementResult result)
	{
		PackRequirement requirement = result.resolvedRequirement.requirement;
		return requirement.enabled && requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
			&& requirement.location != LocationScope.EQUIPMENT_ONLY;
	}

	private boolean isEquipmentCheck(RequirementResult result)
	{
		PackRequirement requirement = result.resolvedRequirement.requirement;
		return requirement.enabled && requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
			&& requirement.location == LocationScope.EQUIPMENT_ONLY;
	}

	private boolean isManualCheck(RequirementResult result)
	{
		PackRequirement requirement = result.resolvedRequirement.requirement;
		return requirement.enabled && requirement.measurement == MeasurementType.MANUAL_CONFIRMATION;
	}

	private boolean isSatisfied(RequirementResult result)
	{
		return result.status == RequirementStatus.SATISFIED || result.status == RequirementStatus.IGNORED;
	}
}

