		copy.maximum = maximum;
		copy.requiredEquipmentSlot = requiredEquipmentSlot;
		copy.fixedInventorySlot = fixedInventorySlot;
		copy.recommendation = recommendation;
		copy.recommendedSlots = recommendedSlots;
		copy.notes = notes;
		for (MatchOption option : alternatives)
		{
