/**
 * Offline, reviewable starter packs based on the linked OSRS strategy guides.
 * They deliberately focus on visible inventory supplies; users should edit them
 * for their stats, gear, route, risk tolerance, and trip length.
 */
public class BuiltInPresetService
{
	private static final int PRESET_VERSION = 3;
	private static final String REVIEWED_ON = "2026-09-03";
	private final Map<String, Definition> definitions = new LinkedHashMap<>();

	public BuiltInPresetService()
	{
		registerMm2Barraging();
		registerFightCaves();
		registerVorkath();
		registerZulrah();
		registerHydra();
		registerBarrows();
		registerGraardor();
		registerWhisperer();
		registerMm2Glough();
		registerSeren();
		registerVanstrom();
		registerDragonSlayerTwoVorkath();
		registerResearchCatalog();
	}

	public List<PresetSummary> summaries()
	{
		List<PresetSummary> summaries = new ArrayList<>();
		for (Definition definition : definitions.values())
		{
			summaries.add(definition.summary);
		}
		return Collections.unmodifiableList(summaries);
	}

	public Pack create(String key)
	{
		Definition definition = definitions.get(key);
		if (definition == null)
		{
			throw new IllegalArgumentException("Unknown built-in preset: " + key);
		}
		return definition.pack.copy();
	}

	public Pack reset(Pack current)
	{
		if (current == null || current.presetKey == null)
		{
			throw new IllegalArgumentException("This pack was not installed from a built-in preset");
		}
		Pack replacement = create(current.presetKey);
		replacement.id = current.id;
		return replacement;
	}

	public boolean supports(String key)
	{
		return definitions.containsKey(key);
	}

	private void registerMm2Barraging()
	{
		String key = "training.mm2_ice_barrage";
		Pack pack = pack(key, "Training", "MM2 maniacal monkeys — Ice Barrage");
		pack.requirements.add(doses(key, "prayer", "Prayer restoration", 16, true,
			"Guide baseline: four 4-dose prayer potions. Monkeys commonly drop 1-dose prayer potions.",
			"prayer_potion", "Prayer potion", "super_restore", "Super restore", "sanfew_serum", "Sanfew serum"));
		pack.requirements.add(items(key, "rune_pouch", "Rune pouch", 1, true,
			"PackCheck cannot inspect pouch contents. Ice Barrage consumes 2 blood, 4 death, and 6 water runes per cast; a Kodai wand supplies water runes.",
			ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH,
			ItemID.DIVINE_RUNE_POUCH_TROUVER));
		pack.requirements.add(items(key, "light", "Light source", 1, true,
			"Kandarin headgear may replace a carried light source.", ItemID.BULLSEYE_LANTERN_LIT,
			ItemID.OIL_LANTERN_LIT, ItemID.CANDLE_LANTERN_LIT, ItemID.CANDLE_LANTERN_BLACK_LIT));
		pack.requirements.add(items(key, "exit", "Exit teleport", 1, true,
