	private Pack pack(String key, String category, String name)
	{
		Pack pack = new Pack();
		pack.id = "preset:" + key;
		pack.name = "[" + category + "] " + name;
		pack.type = PackType.INVENTORY;
		pack.presetKey = key;
		pack.presetVersion = PRESET_VERSION;
		pack.extraItemMode = ExtraItemMode.IGNORE;
		return pack;
	}

	private void register(Pack pack, String category, String name, String description, String sourceUrl)
	{
		boolean hasRunePouch = pack.requirements.stream()
			.anyMatch(requirement -> requirement.displayName.toLowerCase().contains("rune pouch"));
		boolean hasRuneCheck = pack.requirements.stream()
			.anyMatch(requirement -> requirement.measurement == MeasurementType.MANUAL_CONFIRMATION
				&& requirement.displayName.toLowerCase().contains("rune pouch"));
		if (hasRunePouch && !hasRuneCheck)
		{
			pack.requirements.add(manual(pack.presetKey, "manual_rune_pouch", "Rune pouch contents",
				"Confirm the runes required by this method. PackCheck can see the pouch, not its contents."));
		}
		int requiredPlannedSlots = 0;
		pack.presetSourceUrl = sourceUrl;
		List<String> checklist = new ArrayList<>();
		for (PackRequirement requirement : pack.requirements)
		{
			if (requirement.required)
			{
				requiredPlannedSlots += requirement.recommendedSlots;
			}
			String target = requirement.recommendation == null || requirement.recommendation.isEmpty()
				? Integer.toString(requirement.minimum) : requirement.recommendation;
			String kind = requirement.measurement == MeasurementType.MANUAL_CONFIRMATION ? "Manual"
				: requirement.required ? "Required" : "Optional";
			checklist.add(kind + " | "
				+ requirement.displayName + " | " + target);
		}
		if (requiredPlannedSlots != pack.recommendedInventorySlots)
		{
			throw new IllegalStateException(pack.presetKey + " allocates " + requiredPlannedSlots
				+ " required slots but declares " + pack.recommendedInventorySlots);
		}
		PresetSummary summary = new PresetSummary(pack.presetKey, category, name, description, sourceUrl,
			pack.presetMethod, pack.presetPlanNotes, pack.presetReviewedOn, pack.recommendedInventorySlots,
			pack.switchInventorySlots, pack.lootInventorySlots, pack.flexibleInventorySlots, PRESET_VERSION, checklist);
		definitions.put(pack.presetKey, new Definition(summary, pack));
	}

	private void plan(Pack pack, String method, String notes, int plannedSlots, int flexibleSlots)
	{
		plan(pack, method, notes, plannedSlots, 0, flexibleSlots);
	}

	private void plan(Pack pack, String method, String notes, int plannedSlots, int switchSlots, int lootSlots)
	{
		if (plannedSlots < 0 || switchSlots < 0 || lootSlots < 0
			|| plannedSlots + switchSlots + lootSlots != 28)
		{
			throw new IllegalArgumentException("Preset inventory plan must total 28 slots");
		}
		pack.presetMethod = method;
		pack.presetPlanNotes = notes;
		pack.presetReviewedOn = REVIEWED_ON;
		pack.recommendedInventorySlots = plannedSlots;
		pack.switchInventorySlots = switchSlots;
		pack.lootInventorySlots = lootSlots;
		pack.flexibleInventorySlots = switchSlots + lootSlots;
	}

	private void registerResearchCatalog()
	{
		ResearchPresetRuleFactory rules = new ResearchPresetRuleFactory();
		for (ResearchPresetCatalog.Entry entry : new ResearchPresetCatalog().load())
		{
			Pack pack = pack(entry.key, entry.category, entry.activity + " — " + entry.method);
			rules.populate(pack, entry);
			String notes = "Inventory-only starter. " + entry.plannedSlots + " checked slots, "
				+ entry.switchSlots + " player-selected switch slots, and " + entry.lootSlots
				+ " loot/flexible slots. Research confidence: " + entry.confidence + ".";
			if (entry.notes != null && !entry.notes.isEmpty())
			{
				notes += " " + entry.notes;
			}
			plan(pack, entry.method, notes, entry.plannedSlots, entry.switchSlots, entry.lootSlots);
			register(pack, entry.category, entry.activity + " — " + entry.method,
				"A researched 28-slot inventory starter with combat equipment kept outside the preset.",
				entry.sourceUrl);
		}
	}

	private PackRequirement items(String presetKey, String ruleKey, String name, int minimum, boolean required,
		String notes, int... itemIds)
	{
		PackRequirement requirement = baseRequirement(presetKey, ruleKey, name, minimum, required, notes);
		requirement.measurement = MeasurementType.ITEM_QUANTITY;
		requirement.alternatives.add(exactOption(name, itemIds));
		requirement.recommendedSlots = minimum;
		requirement.recommendation = minimum + " x " + name;
		return requirement;
	}

	private PackRequirement stack(String presetKey, String ruleKey, String name, int minimum, boolean required,
		String notes, int... itemIds)
	{
		PackRequirement requirement = items(presetKey, ruleKey, name, minimum, required, notes, itemIds);
		requirement.recommendedSlots = 1;
		requirement.recommendation = minimum + "+ in one stack";
		return requirement;
	}

	private PackRequirement highFood(String presetKey, String ruleKey, String name, int minimum, boolean required,
		String notes)
	{
		return items(presetKey, ruleKey, name, minimum, required, notes, ItemID.SHARK, ItemID.MANTARAY,
			ItemID.ANGLERFISH, ItemID.DARK_CRAB, ItemID.MONKFISH, ItemID.POTATO_TUNA_SWEETCORN);
	}

	private PackRequirement doses(String presetKey, String ruleKey, String name, int minimum, boolean required,
		String notes, String... familyKeyLabels)
	{
		PackRequirement requirement = baseRequirement(presetKey, ruleKey, name, minimum, required, notes);
		requirement.measurement = MeasurementType.TOTAL_DOSES;
		addFamilies(requirement, familyKeyLabels);
		requirement.recommendedSlots = (minimum + 3) / 4;
		requirement.recommendation = requirement.recommendedSlots + " full 4-dose bottle"
			+ (requirement.recommendedSlots == 1 ? "" : "s") + " (" + minimum + " total doses)";
		return requirement;
	}

	private PackRequirement constraintDoses(String presetKey, String ruleKey, String name, int minimum,
		boolean required, String notes, String... familyKeyLabels)
	{
		PackRequirement requirement = doses(presetKey, ruleKey, name, minimum, required, notes, familyKeyLabels);
		requirement.recommendedSlots = 0;
		requirement.recommendation = "At least " + minimum + " doses within the plan";
		return requirement;
	}

	private PackRequirement charges(String presetKey, String ruleKey, String name, int minimum, boolean required,
		String notes, String... familyKeyLabels)
	{
		PackRequirement requirement = baseRequirement(presetKey, ruleKey, name, minimum, required, notes);
		requirement.measurement = MeasurementType.KNOWN_CHARGES;
		addFamilies(requirement, familyKeyLabels);
		requirement.recommendedSlots = 1;
		requirement.recommendation = "1 item with at least " + minimum + " known charges";
		return requirement;
	}

	private PackRequirement manual(String presetKey, String ruleKey, String name, String notes)
	{
		PackRequirement requirement = baseRequirement(presetKey, ruleKey, name, 1, true, notes);
		requirement.measurement = MeasurementType.MANUAL_CONFIRMATION;
		requirement.recommendedSlots = 0;
		requirement.recommendation = "Confirm before leaving the bank";
		return requirement;
	}

	private PackRequirement baseRequirement(String presetKey, String ruleKey, String name, int minimum,
		boolean required, String notes)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.id = presetKey + ":" + ruleKey;
		requirement.displayName = name;
		requirement.minimum = minimum;
		requirement.required = required;
		requirement.location = LocationScope.INVENTORY_ONLY;
		requirement.notes = notes;
		return requirement;
	}

	private void addFamilies(PackRequirement requirement, String... familyKeyLabels)
	{
		if (familyKeyLabels.length % 2 != 0)
		{
			throw new IllegalArgumentException("Family keys and labels must be paired");
		}
		for (int index = 0; index < familyKeyLabels.length; index += 2)
		{
			requirement.alternatives.add(MatchOption.family(familyKeyLabels[index], familyKeyLabels[index + 1]));
		}
	}

	private MatchOption exactOption(String label, int... itemIds)
	{
		MatchOption option = new MatchOption();
		option.label = label;
		for (int itemId : itemIds)
		{
			option.itemIds.add(itemId);
		}
		return option;
	}

	private static final class Definition
	{
		private final PresetSummary summary;
		private final Pack pack;

		private Definition(PresetSummary summary, Pack pack)
		{
			this.summary = summary;
			this.pack = pack;
		}
	}
}

package com.packcheck.service;

import com.packcheck.model.ItemStackSnapshot;
import com.packcheck.model.LocationScope;
import com.packcheck.model.MatchOption;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.Pack;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackSnapshot;
import com.packcheck.model.PackType;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class CaptureService
{
	private final DoseService doseService;
	private final ChargeService chargeService;

	public CaptureService(DoseService doseService, ChargeService chargeService)
	{
		this.doseService = doseService;
		this.chargeService = chargeService;
	}

	public Pack capture(String name, PackSnapshot snapshot)
	{
		return capture(name, snapshot, PackType.TRIP);
	}

	public Pack capture(String name, PackSnapshot snapshot, PackType type)
	{
		Pack pack = new Pack();
		pack.name = name;
		pack.type = type == null ? PackType.TRIP : type;
		if (pack.type != PackType.EQUIPMENT)
		{
			pack.requirements.addAll(captureLocation(snapshot.inventory, LocationScope.INVENTORY_ONLY));
		}
		if (pack.type != PackType.INVENTORY)
		{
			pack.requirements.addAll(captureLocation(snapshot.equipment, LocationScope.EQUIPMENT_ONLY));
		}
		return pack;
	}

	private List<PackRequirement> captureLocation(List<ItemStackSnapshot> items, LocationScope location)
	{
		Map<String, List<ItemStackSnapshot>> groups = new LinkedHashMap<>();
		for (ItemStackSnapshot item : items)
		{
			String doseFamily = doseService.familyForItem(item.itemId);
			String chargeFamily = chargeService.familyForItem(item.itemId);
			String key = doseFamily != null ? "dose:" + doseFamily
				: chargeFamily != null ? "charge:" + chargeFamily : "item:" + item.itemId;
			groups.computeIfAbsent(key, ignored -> new ArrayList<>()).add(item);
		}

		List<PackRequirement> requirements = new ArrayList<>();
		for (Map.Entry<String, List<ItemStackSnapshot>> entry : groups.entrySet())
		{
			List<ItemStackSnapshot> group = entry.getValue();
			ItemStackSnapshot first = group.get(0);
			PackRequirement requirement = new PackRequirement();
			requirement.location = location;
			if (location == LocationScope.EQUIPMENT_ONLY)
			{
				requirement.requiredEquipmentSlot = first.slot;
			}

			if (entry.getKey().startsWith("dose:"))
			{
				String family = entry.getKey().substring("dose:".length());
				requirement.displayName = doseService.label(family);
				requirement.measurement = MeasurementType.TOTAL_DOSES;
				requirement.alternatives.add(MatchOption.family(family, doseService.label(family)));
				requirement.minimum = doseService.totalDoses(family, group);
			}
			else if (entry.getKey().startsWith("charge:"))
			{
				String family = entry.getKey().substring("charge:".length());
				requirement.displayName = chargeService.label(family);
				requirement.measurement = MeasurementType.KNOWN_CHARGES;
				requirement.alternatives.add(MatchOption.family(family, chargeService.label(family)));
				requirement.minimum = group.stream().map(item -> chargeService.knownCharges(item.itemId))
					.filter(value -> value != null).mapToInt(Integer::intValue).max().orElse(1);
			}
			else
			{
				requirement.displayName = first.displayName;
				requirement.alternatives.add(MatchOption.exact(first.itemId, first.displayName));
				requirement.minimum = group.stream().mapToInt(item -> Math.max(1, item.quantity)).sum();
			}
			requirements.add(requirement);
		}
		return requirements;
	}
}

