			ItemID.SACK_POTATO_9, ItemID.SACK_POTATO_10);
	}

	private void registerDescending(String key, String label, int maximum, int... itemIds)
	{
		Map<Integer, Integer> charges = new LinkedHashMap<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			charges.put(itemIds[index], maximum - index);
		}
		families.put(key, Collections.unmodifiableMap(charges));
		labels.put(key, label);
	}

	private void registerAscending(String key, String label, int... itemIds)
	{
		Map<Integer, Integer> charges = new LinkedHashMap<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			charges.put(itemIds[index], index + 1);
		}
		families.put(key, Collections.unmodifiableMap(charges));
		labels.put(key, label);
	}

	private void registerFromZero(String key, String label, int... itemIds)
	{
		Map<Integer, Integer> charges = new LinkedHashMap<>();
		for (int index = 0; index < itemIds.length; index++)
		{
			charges.put(itemIds[index], index);
		}
		families.put(key, Collections.unmodifiableMap(charges));
		labels.put(key, label);
	}

	private void registerVariants(String key, String label, int[][] itemIdsByCharge)
	{
		Map<Integer, Integer> charges = new LinkedHashMap<>();
		for (int index = 0; index < itemIdsByCharge.length; index++)
		{
			for (int itemId : itemIdsByCharge[index])
			{
				charges.put(itemId, index + 1);
			}
		}
		families.put(key, Collections.unmodifiableMap(charges));
		labels.put(key, label);
	}

	public boolean supports(String familyKey)
	{
		return families.containsKey(familyKey);
	}

	public boolean matches(String familyKey, int itemId)
	{
		Map<Integer, Integer> family = families.get(familyKey);
		return family != null && family.containsKey(itemId);
	}

	public Integer charges(String familyKey, int itemId)
	{
		Map<Integer, Integer> family = families.get(familyKey);
		return family == null ? null : family.get(itemId);
	}

	public Integer knownCharges(int itemId)
	{
		for (Map<Integer, Integer> family : families.values())
		{
			Integer value = family.get(itemId);
			if (value != null)
			{
				return value;
			}
		}
		return null;
	}

	public String familyForItem(int itemId)
	{
		for (Map.Entry<String, Map<Integer, Integer>> entry : families.entrySet())
		{
			if (entry.getValue().containsKey(itemId))
			{
				return entry.getKey();
			}
		}
		return null;
	}

	public String label(String familyKey)
	{
		return labels.getOrDefault(familyKey, familyKey);
	}

	public List<String> supportedFamilies()
	{
		return Collections.unmodifiableList(new ArrayList<>(families.keySet()));
	}
}

