	private void register(String key, String label, int... itemIdsByDose)
	{
		Map<Integer, Integer> doses = new LinkedHashMap<>();
		for (int index = 0; index < itemIdsByDose.length; index++)
		{
			doses.put(itemIdsByDose[index], index + 1);
		}
		families.put(key, Collections.unmodifiableMap(doses));
		labels.put(key, label);
	}

	public boolean supports(String familyKey)
	{
		return families.containsKey(familyKey);
	}

	public boolean matches(String familyKey, int itemId)
	{
		Map<Integer, Integer> family = families.get(familyKey);
		return family != null && family.containsKey(itemId);
	}

	public Integer doses(String familyKey, int itemId)
	{
		Map<Integer, Integer> family = families.get(familyKey);
		return family == null ? null : family.get(itemId);
	}

	public int totalDoses(String familyKey, List<ItemStackSnapshot> items)
	{
		int total = 0;
		for (ItemStackSnapshot item : items)
		{
			Integer doses = doses(familyKey, item.itemId);
			if (doses != null)
			{
				total += doses * Math.max(1, item.quantity);
			}
		}
		return total;
	}

	public String familyForItem(int itemId)
	{
		for (Map.Entry<String, Map<Integer, Integer>> entry : families.entrySet())
		{
			if (entry.getValue().containsKey(itemId))
			{
				return entry.getKey();
			}
		}
		return null;
	}

	public String label(String familyKey)
	{
		return labels.getOrDefault(familyKey, familyKey);
	}

	public List<String> supportedFamilies()
	{
		return Collections.unmodifiableList(new ArrayList<>(families.keySet()));
	}
}

package com.packcheck.service;

import com.packcheck.model.MatchOption;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemVariationMapping;

public class ItemFamilyService
{
	private final DoseService doseService;
	private final ChargeService chargeService;
	private final Map<String, Set<Integer>> explicitFamilies = new LinkedHashMap<>();

	public ItemFamilyService(DoseService doseService, ChargeService chargeService)
	{
		this.doseService = doseService;
		this.chargeService = chargeService;
	}

	public void registerExplicitFamily(String key, Set<Integer> itemIds)
	{
		explicitFamilies.put(key, new LinkedHashSet<>(itemIds));
	}

	public boolean matches(MatchOption option, int itemId)
	{
		if (option.familyKey != null)
		{
			Set<Integer> explicit = explicitFamilies.get(option.familyKey);
			if (explicit != null && explicit.contains(itemId))
			{
				return true;
			}
			if (doseService.matches(option.familyKey, itemId) || chargeService.matches(option.familyKey, itemId))
			{
				return true;
			}
		}

		for (int expectedId : option.itemIds)
		{
			if (expectedId == itemId)
			{
				return true;
			}
			if (option.matchVariations && ItemVariationMapping.map(expectedId) == ItemVariationMapping.map(itemId))
			{
				return true;
			}
		}
		return false;
	}

	public boolean supportsFamily(String key)
	{
		return explicitFamilies.containsKey(key) || doseService.supports(key) || chargeService.supports(key);
	}
}

package com.packcheck.service;

import com.packcheck.PackCheckConfig;
import com.packcheck.model.PackEvaluation;
import java.awt.Color;
import java.awt.TrayIcon;
import net.runelite.client.Notifier;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;

public class NotificationCoordinator
{
	private final Notifier notifier;
	private final PackCheckConfig config;
	private Boolean previouslyReady;
	private long lastNotificationMillis = Long.MIN_VALUE;

	public NotificationCoordinator(Notifier notifier, PackCheckConfig config)
	{
		this.notifier = notifier;
		this.config = config;
	}

	public void reset()
	{
		previouslyReady = null;
	}

	public void onEvaluation(PackEvaluation evaluation, boolean afterBank, long nowMillis)
	{
		if (evaluation.packName.isEmpty())
		{
			previouslyReady = null;
			return;
		}
		String message = null;
		if (afterBank && config.notifyAfterBank() && !evaluation.ready)
		{
			message = evaluation.packName + " is not ready: " + evaluation.requiredFailureCount() + " required issue(s)";
		}
		else if (previouslyReady != null && !previouslyReady && evaluation.ready && config.notifyWhenReady())
		{
			message = evaluation.packName + " is ready";
		}
		else if (previouslyReady != null && previouslyReady && !evaluation.ready && config.notifyWhenInvalid())
		{
			message = evaluation.packName + " is no longer ready: " + evaluation.requiredFailureCount() + " required issue(s)";
		}
		previouslyReady = evaluation.ready;
		if (message == null)
		{
			return;
		}
		if (config.includeOptionalWarnings() && evaluation.warningCount() > 0)
		{
			message += ", " + evaluation.warningCount() + " optional warning(s)";
		}
		long cooldownMillis = Math.max(0, config.notificationCooldownSeconds()) * 1000L;
		if (lastNotificationMillis != Long.MIN_VALUE && nowMillis - lastNotificationMillis < cooldownMillis)
		{
			return;
		}
		lastNotificationMillis = nowMillis;
		if (config.notificationSound())
		{
			notifier.notify(message);
		}
		else
		{
			Notification silent = new Notification(true, true, true, true, TrayIcon.MessageType.NONE,
				RequestFocusType.OFF, NotificationSound.OFF, null, 0, 5000, false,
				FlashNotification.DISABLED, Color.BLACK, true);
			notifier.notify(silent, message);
		}
	}
}

package com.packcheck.service;

import com.packcheck.model.ExtraItemMode;
import com.packcheck.model.ItemStackSnapshot;
import com.packcheck.model.LocationScope;
import com.packcheck.model.MatchOption;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.PackEvaluation;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackResolution;
import com.packcheck.model.PackSnapshot;
import com.packcheck.model.RequirementResult;
import com.packcheck.model.RequirementStatus;
import com.packcheck.model.ResolvedRequirement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Pure validation service. It has no client, event, persistence, or Swing dependencies. */
public class PackEvaluator
{
	private final ItemFamilyService itemFamilyService;
	private final DoseService doseService;
	private final ChargeService chargeService;

	public PackEvaluator(ItemFamilyService itemFamilyService, DoseService doseService, ChargeService chargeService)
	{
		this.itemFamilyService = itemFamilyService;
		this.doseService = doseService;
		this.chargeService = chargeService;
	}

	public PackEvaluation evaluate(PackResolution resolution, PackSnapshot snapshot)
	{
		return evaluate(resolution, snapshot, Collections.emptySet());
	}

	public PackEvaluation evaluate(PackResolution resolution, PackSnapshot snapshot,
		Set<String> confirmedManualRequirementIds)
	{
		List<RequirementResult> results = new ArrayList<>();
		Set<ItemStackSnapshot> governedItems = new HashSet<>();
		for (ResolvedRequirement resolvedRequirement : resolution.requirements)
		{
			RequirementResult result = evaluateRequirement(resolvedRequirement, snapshot,
				confirmedManualRequirementIds == null ? Collections.emptySet() : confirmedManualRequirementIds);
			results.add(result);
			governedItems.addAll(result.matchedItems);
		}

		List<RequirementResult> extras = evaluateExtras(resolution.extraItemMode, snapshot, governedItems);
		boolean ready = results.stream().noneMatch(RequirementResult::isRequiredFailure)
			&& extras.stream().noneMatch(RequirementResult::isRequiredFailure)
			&& resolution.conflicts.isEmpty();
		return new PackEvaluation(resolution.displayName, results, extras, ready);
	}

	private RequirementResult evaluateRequirement(ResolvedRequirement resolved, PackSnapshot snapshot,
		Set<String> confirmedManualRequirementIds)
	{
		PackRequirement requirement = resolved.requirement;
		if (!requirement.enabled)
		{
			return result(resolved, RequirementStatus.IGNORED, 0, expected(requirement), "Ignored by this pack",
				Collections.emptyList(), Collections.emptyList());
		}
		if (requirement.measurement == MeasurementType.MANUAL_CONFIRMATION)
		{
			boolean confirmed = confirmedManualRequirementIds.contains(requirement.id);
			return result(resolved, confirmed ? RequirementStatus.SATISFIED : RequirementStatus.MANUAL_CHECK,
				confirmed ? 1 : 0, 1, confirmed ? "Confirmed for this trip" : "Needs your confirmation",
				Collections.emptyList(), Collections.emptyList());
		}
		if (requirement.alternatives == null || requirement.alternatives.isEmpty())
		{
			return result(resolved, RequirementStatus.UNSUPPORTED, 0, expected(requirement),
				"No stable item or family matcher is configured", Collections.emptyList(), Collections.emptyList());
		}

		List<ItemStackSnapshot> inventoryMatches = matching(snapshot.inventory, requirement);
		List<ItemStackSnapshot> equipmentMatches = matching(snapshot.equipment, requirement);
		List<ItemStackSnapshot> allMatches = new ArrayList<>(inventoryMatches);
		allMatches.addAll(equipmentMatches);
		List<ItemStackSnapshot> allowedMatches = allowed(requirement, inventoryMatches, equipmentMatches);

		if (requirement.requiredEquipmentSlot != null && !allMatches.isEmpty()
			&& equipmentMatches.stream().noneMatch(item -> item.slot == requirement.requiredEquipmentSlot))
		{
			return result(resolved, RequirementStatus.WRONG_EQUIPMENT_SLOT, 0, expected(requirement),
				"Present, but not in equipment slot " + requirement.requiredEquipmentSlot,
				alternativeLabels(requirement, allMatches), allMatches);
		}

		if (requirement.fixedInventorySlot != null && !allMatches.isEmpty()
			&& inventoryMatches.stream().noneMatch(item -> item.slot == requirement.fixedInventorySlot))
		{
			return result(resolved, RequirementStatus.WRONG_INVENTORY_SLOT, 0, expected(requirement),
				"Present, but not in inventory slot " + (requirement.fixedInventorySlot + 1),
				alternativeLabels(requirement, allMatches), allMatches);
		}

		if (allowedMatches.isEmpty() && !allMatches.isEmpty())
		{
			return result(resolved, RequirementStatus.WRONG_LOCATION, 0, expected(requirement),
				"Present in " + wrongLocation(requirement), alternativeLabels(requirement, allMatches), allMatches);
		}

		switch (requirement.measurement)
		{
			case TOTAL_DOSES:
				return evaluateDoses(resolved, allowedMatches);
			case KNOWN_CHARGES:
				return evaluateCharges(resolved, allowedMatches);
			case ITEM_QUANTITY:
			default:
				return evaluateQuantity(resolved, allowedMatches);
		}
	}

	private RequirementResult evaluateQuantity(ResolvedRequirement resolved, List<ItemStackSnapshot> matches)
	{
		int actual = matches.stream().mapToInt(item -> Math.max(1, item.quantity)).sum();
		return compare(resolved, actual, RequirementStatus.INSUFFICIENT_QUANTITY, "items",
			alternativeLabels(resolved.requirement, matches), matches);
	}

	private RequirementResult evaluateDoses(ResolvedRequirement resolved, List<ItemStackSnapshot> matches)
	{
		PackRequirement requirement = resolved.requirement;
		boolean supported = requirement.alternatives.stream().anyMatch(option -> option.familyKey != null
			&& doseService.supports(option.familyKey));
		if (!supported)
		{
			int fallbackQuantity = matches.stream().mapToInt(item -> Math.max(1, item.quantity)).sum();
			RequirementResult fallback = compare(resolved, fallbackQuantity, RequirementStatus.INSUFFICIENT_QUANTITY,
				"items; dose metadata is unavailable", alternativeLabels(requirement, matches), matches);
			if (matches.isEmpty())
			{
				return result(resolved, RequirementStatus.UNSUPPORTED, 0, expected(requirement),
					"Dose family unsupported; configure item quantity instead", Collections.emptyList(), matches);
			}
			return fallback;
		}

		int total = 0;
		for (ItemStackSnapshot item : matches)
		{
			int bestDose = 0;
			for (MatchOption option : requirement.alternatives)
			{
				if (option.familyKey != null && itemFamilyService.matches(option, item.itemId))
				{
					Integer doses = doseService.doses(option.familyKey, item.itemId);
					bestDose = Math.max(bestDose, doses == null ? 0 : doses);
				}
			}
			total += bestDose * Math.max(1, item.quantity);
		}
		return compare(resolved, total, RequirementStatus.INSUFFICIENT_DOSES, "doses",
			alternativeLabels(requirement, matches), matches);
	}

	private RequirementResult evaluateCharges(ResolvedRequirement resolved, List<ItemStackSnapshot> matches)
	{
		PackRequirement requirement = resolved.requirement;
		int maximumKnown = -1;
		boolean matchedUnknown = false;
		for (ItemStackSnapshot item : matches)
		{
			Integer known = null;
			for (MatchOption option : requirement.alternatives)
			{
				if (itemFamilyService.matches(option, item.itemId))
				{
					known = option.familyKey == null ? chargeService.knownCharges(item.itemId)
						: chargeService.charges(option.familyKey, item.itemId);
					if (known != null)
					{
						maximumKnown = Math.max(maximumKnown, known);
					}
				}
			}
			matchedUnknown |= known == null;
		}

		if (!matches.isEmpty() && maximumKnown < 0 && matchedUnknown)
		{
			return result(resolved, RequirementStatus.UNKNOWN_CHARGES, 0, expected(requirement),
				"Item is present, but its charge count is not exposed by a reliable supported variant",
				alternativeLabels(requirement, matches), matches);
		}
		return compare(resolved, Math.max(0, maximumKnown), RequirementStatus.INSUFFICIENT_CHARGES,
			"known charges", alternativeLabels(requirement, matches), matches);
	}

	private RequirementResult compare(ResolvedRequirement resolved, int actual, RequirementStatus insufficient,
		String unit, List<String> alternatives, List<ItemStackSnapshot> matches)
	{
		PackRequirement requirement = resolved.requirement;
		int expected = expected(requirement);
		if (actual == 0)
		{
			RequirementStatus status = requirement.required ? RequirementStatus.MISSING : RequirementStatus.OPTIONAL_MISSING;
			return result(resolved, status, actual, expected,
				"0 / " + expected + " " + unit + " - need " + expected, alternatives, matches);
		}
		if (actual < expected)
		{
			return result(resolved, insufficient, actual, expected, actual + " / " + expected + " " + unit
				+ " - need " + (expected - actual) + " more",
				alternatives, matches);
		}
		Integer maximum = requirement.exact != null ? requirement.exact : requirement.maximum;
		if (maximum != null && actual > maximum)
		{
			return result(resolved, RequirementStatus.EXTRA_ITEM, actual, maximum,
				actual + " present; maximum " + maximum + " " + unit, alternatives, matches);
		}
		return result(resolved, RequirementStatus.SATISFIED, actual, expected,
			actual + " / " + expected + " " + unit, alternatives, matches);
	}

	private List<RequirementResult> evaluateExtras(ExtraItemMode mode, PackSnapshot snapshot,
		Set<ItemStackSnapshot> governedItems)
	{
		if (mode == ExtraItemMode.IGNORE)
		{
			return Collections.emptyList();
		}
		List<RequirementResult> extras = new ArrayList<>();
		List<ItemStackSnapshot> all = new ArrayList<>(snapshot.inventory);
		all.addAll(snapshot.equipment);
		for (ItemStackSnapshot item : all)
		{
			if (item.itemId <= 0 || governedItems.contains(item))
			{
				continue;
			}
			PackRequirement requirement = new PackRequirement();
			requirement.displayName = item.displayName == null ? "Unexpected item " + item.itemId : item.displayName;
			requirement.required = mode == ExtraItemMode.ENFORCE_EXACT;
			ResolvedRequirement resolved = new ResolvedRequirement(requirement, "extras", "Unexpected items", false);
			extras.add(result(resolved, RequirementStatus.EXTRA_ITEM, item.quantity, 0,
				"Unexpected " + (snapshot.inventory.contains(item) ? "inventory" : "equipment") + " item",
				Collections.emptyList(), Collections.singletonList(item)));
		}
		return extras;
	}

	private List<ItemStackSnapshot> matching(List<ItemStackSnapshot> items, PackRequirement requirement)
	{
		List<ItemStackSnapshot> matches = new ArrayList<>();
		for (ItemStackSnapshot item : items)
		{
			if (item.itemId <= 0)
			{
				continue;
			}
			if (requirement.alternatives.stream().anyMatch(option -> itemFamilyService.matches(option, item.itemId)))
			{
				matches.add(item);
			}
		}
		return matches;
	}

	private List<ItemStackSnapshot> allowed(PackRequirement requirement, List<ItemStackSnapshot> inventory,
		List<ItemStackSnapshot> equipment)
	{
		List<ItemStackSnapshot> allowed = new ArrayList<>();
		if (requirement.location != LocationScope.EQUIPMENT_ONLY)
		{
			allowed.addAll(inventory);
		}
		if (requirement.location != LocationScope.INVENTORY_ONLY)
		{
			allowed.addAll(equipment);
		}
		if (requirement.requiredEquipmentSlot != null)
		{
			allowed.removeIf(item -> !equipment.contains(item) || item.slot != requirement.requiredEquipmentSlot);
		}
		if (requirement.fixedInventorySlot != null)
		{
			allowed.removeIf(item -> !inventory.contains(item) || item.slot != requirement.fixedInventorySlot);
		}
		return allowed;
	}

	private List<String> alternativeLabels(PackRequirement requirement, List<ItemStackSnapshot> matches)
	{
		Set<String> labels = new LinkedHashSet<>();
		for (MatchOption option : requirement.alternatives)
		{
			if (matches.stream().anyMatch(item -> itemFamilyService.matches(option, item.itemId)))
			{
				labels.add(option.label);
			}
		}
		return new ArrayList<>(labels);
	}

	private int expected(PackRequirement requirement)
	{
		return requirement.exact == null ? Math.max(0, requirement.minimum) : Math.max(0, requirement.exact);
	}

	private String wrongLocation(PackRequirement requirement)
	{
		return requirement.location == LocationScope.INVENTORY_ONLY ? "equipment" : "inventory";
	}

	private RequirementResult result(ResolvedRequirement resolved, RequirementStatus status, int actual,
		int expected, String detail, List<String> alternatives, List<ItemStackSnapshot> matchedItems)
	{
		return new RequirementResult(resolved, status, actual, expected, detail, alternatives, matchedItems);
	}
}

package com.packcheck.service;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.packcheck.model.ImportPreview;
import com.packcheck.model.LocationScope;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.Pack;
import com.packcheck.model.PackComposition;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackStore;
import com.packcheck.model.PackType;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Clock;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;
import net.runelite.client.RuneLite;

public class PackRepository
{
	private static final String ENCODED_PREFIX = "packcheck:";

	private final Gson gson;
	private final Path directory;
	private final Clock clock;

	public PackRepository(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("packcheck"), Clock.systemUTC());
	}

	public PackRepository(Gson gson, Path directory, Clock clock)
	{
		this.gson = gson;
		this.directory = directory;
		this.clock = clock;
	}

	public PackStore load(String profileKey) throws IOException
	{
		String safeProfile = sanitizeProfile(profileKey);
		Path file = profileFile(safeProfile);
		if (!Files.exists(file))
		{
			return emptyStore(safeProfile);
		}

		try
		{
			String json = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
			PackStore store = gson.fromJson(json, PackStore.class);
			if (store == null)
			{
				throw new JsonParseException("Empty PackCheck document");
			}
			if (store.schemaVersion > PackStore.CURRENT_SCHEMA_VERSION)
			{
				throw new IOException("PackCheck data uses newer schema version " + store.schemaVersion
					+ "; this version supports up to " + PackStore.CURRENT_SCHEMA_VERSION);
			}
			if (store.schemaVersion < PackStore.CURRENT_SCHEMA_VERSION)
			{
				backup(file, "backup-v" + store.schemaVersion);
				store = migrate(store, safeProfile);
				save(store);
			}
			normalize(store, safeProfile);
			return store;
		}
		catch (JsonParseException | IllegalStateException exception)
		{
			backup(file, "malformed");
			return emptyStore(safeProfile);
		}
	}

	public void save(PackStore store) throws IOException
	{
		normalize(store, sanitizeProfile(store.profileKey));
		Files.createDirectories(directory);
		Path destination = profileFile(store.profileKey);
		Path temporary = directory.resolve(destination.getFileName().toString() + ".tmp");
		Files.write(temporary, gson.toJson(store).getBytes(StandardCharsets.UTF_8));
		try
		{
			Files.move(temporary, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException ignored)
		{
			Files.move(temporary, destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	public String exportJson(PackStore store)
	{
		return gson.toJson(store);
	}

	public String exportEncoded(PackStore store)
	{
		String encoded = Base64.getUrlEncoder().withoutPadding()
			.encodeToString(exportJson(store).getBytes(StandardCharsets.UTF_8));
		return ENCODED_PREFIX + encoded;
	}

	public ImportPreview previewImport(String input, PackStore existing)
	{
		String json = decodeIfNeeded(input == null ? "" : input.trim());
		PackStore imported;
		try
		{
			imported = gson.fromJson(json, PackStore.class);
		}
		catch (JsonParseException | IllegalStateException exception)
		{
			throw new IllegalArgumentException("Import is not valid PackCheck JSON", exception);
		}
		if (imported == null || imported.packs == null)
		{
			throw new IllegalArgumentException("Import does not contain PackCheck pack data");
		}
		if (imported.schemaVersion > PackStore.CURRENT_SCHEMA_VERSION)
		{
			throw new IllegalArgumentException("Import schema " + imported.schemaVersion + " is newer than supported schema "
				+ PackStore.CURRENT_SCHEMA_VERSION);
		}
		if (imported.schemaVersion < PackStore.CURRENT_SCHEMA_VERSION)
		{
			imported = migrate(imported, existing.profileKey);
		}
		normalize(imported, existing.profileKey);
		Set<String> existingIds = new HashSet<>();
		for (Pack pack : existing.packs)
		{
			existingIds.add(pack.id);
		}
		int collisions = 0;
		for (Pack pack : imported.packs)
		{
			if (existingIds.contains(pack.id))
			{
				collisions++;
			}
		}
		String summary = imported.packs.size() + " pack(s), " + collisions
			+ " ID collision(s). Colliding IDs are regenerated when merging.";
		return new ImportPreview(imported, imported.packs.size(), collisions, summary);
	}

	public PackStore merge(PackStore existing, ImportPreview preview, boolean replace)
	{
		PackStore result = replace ? emptyStore(existing.profileKey) : cloneStore(existing);
		Map<String, String> remappedIds = new HashMap<>();
		Set<String> used = new HashSet<>();
		for (Pack pack : result.packs)
		{
			used.add(pack.id);
		}

		for (Pack importedPack : preview.importedStore.packs)
		{
			String oldId = importedPack.id;
			String newId = oldId;
			while (newId == null || used.contains(newId))
			{
				newId = UUID.randomUUID().toString();
			}
			remappedIds.put(oldId, newId);
			used.add(newId);
		}

		for (Pack importedPack : preview.importedStore.packs)
		{
			Pack copy = clonePack(importedPack);
			copy.id = remappedIds.get(importedPack.id);
			if (copy.basePackId != null && remappedIds.containsKey(copy.basePackId))
			{
				copy.basePackId = remappedIds.get(copy.basePackId);
			}
			result.packs.add(copy);
		}
		return result;
	}

	public Path profileFile(String profileKey)
	{
		return directory.resolve("packs-" + sanitizeProfile(profileKey) + ".json");
	}

	private String decodeIfNeeded(String input)
	{
		if (!input.startsWith(ENCODED_PREFIX))
		{
			return input;
		}
		try
		{
			byte[] decoded = Base64.getUrlDecoder().decode(input.substring(ENCODED_PREFIX.length()));
			return new String(decoded, StandardCharsets.UTF_8);
		}
		catch (IllegalArgumentException exception)
		{
			throw new IllegalArgumentException("Invalid PackCheck encoded string", exception);
		}
	}

	private PackStore migrate(PackStore store, String profileKey)
	{
		if (store.schemaVersion <= 1)
		{
			store.schemaVersion = 2;
			if (store.composition == null)
			{
				store.composition = new PackComposition();
			}
			store.profileKey = profileKey;
		}
		if (store.schemaVersion <= 2)
		{
			store.schemaVersion = 3;
		}
		if (store.schemaVersion <= 3)
		{
			store.schemaVersion = 4;
		}
		if (store.schemaVersion <= 4)
		{
			store.schemaVersion = 5;
		}
		return store;
	}

	private void normalize(PackStore store, String profileKey)
	{
		store.schemaVersion = PackStore.CURRENT_SCHEMA_VERSION;
		store.profileKey = sanitizeProfile(profileKey);
		if (store.packs == null)
		{
			store.packs = new ArrayList<>();
		}
		if (store.composition == null)
		{
			store.composition = new PackComposition();
		}
		if (store.composition.addOnPackIds == null)
		{
			store.composition.addOnPackIds = new ArrayList<>();
		}
		if (store.composition.conflictResolutions == null)
		{
			store.composition.conflictResolutions = new HashMap<>();
		}
		if (store.composition.confirmedManualRequirementIds == null)
		{
			store.composition.confirmedManualRequirementIds = new HashSet<>();
		}
		for (Pack pack : store.packs)
		{
			if (pack.type == null)
			{
				pack.type = inferType(pack);
			}
			if (pack.switchInventorySlots == 0 && pack.lootInventorySlots == 0
				&& pack.flexibleInventorySlots > 0)
			{
				pack.lootInventorySlots = pack.flexibleInventorySlots;
			}
			pack.flexibleInventorySlots = pack.switchInventorySlots + pack.lootInventorySlots;
			if (pack.presetMethod == null)
			{
				pack.presetMethod = "";
			}
			if (pack.presetPlanNotes == null)
			{
				pack.presetPlanNotes = "";
			}
			if (pack.presetSourceUrl == null)
			{
				pack.presetSourceUrl = "";
			}
			if (pack.presetReviewedOn == null)
			{
				pack.presetReviewedOn = "";
			}
			if (pack.requirements == null)
			{
				pack.requirements = new ArrayList<>();
			}
			if (pack.contextRules == null)
			{
				pack.contextRules = new ArrayList<>();
			}
			for (PackRequirement requirement : pack.requirements)
			{
				if (requirement.location == null)
				{
					requirement.location = LocationScope.INVENTORY_OR_EQUIPMENT;
				}
				if (requirement.measurement == null)
				{
					requirement.measurement = MeasurementType.ITEM_QUANTITY;
				}
				if (requirement.recommendation == null)
				{
					requirement.recommendation = "";
				}
				if (requirement.alternatives == null)
				{
					requirement.alternatives = new ArrayList<>();
				}
			}
		}
		Pack selectedMain = store.packs.stream().filter(pack -> Objects.equals(pack.id, store.composition.mainPackId))
			.findFirst().orElse(null);
		if (selectedMain != null && selectedMain.type == PackType.EQUIPMENT)
		{
			store.composition.equipmentPackId = selectedMain.id;
			store.composition.mainPackId = null;
		}
		Pack selectedEquipment = store.packs.stream()
			.filter(pack -> Objects.equals(pack.id, store.composition.equipmentPackId)).findFirst().orElse(null);
		if (selectedEquipment == null || selectedEquipment.type != PackType.EQUIPMENT)
		{
			store.composition.equipmentPackId = null;
		}
	}

	private PackType inferType(Pack pack)
	{
		boolean inventory = false;
		boolean equipment = false;
		if (pack.requirements != null)
		{
			for (PackRequirement requirement : pack.requirements)
			{
				inventory |= requirement.location != LocationScope.EQUIPMENT_ONLY;
				equipment |= requirement.location == LocationScope.EQUIPMENT_ONLY;
			}
		}
		return inventory && equipment ? PackType.TRIP : equipment ? PackType.EQUIPMENT : PackType.INVENTORY;
	}

	private void backup(Path file, String suffix) throws IOException
	{
		Files.createDirectories(directory);
		Path backup = directory.resolve(file.getFileName().toString() + "." + suffix + "-" + clock.millis() + ".bak");
		Files.copy(file, backup, StandardCopyOption.REPLACE_EXISTING);
	}

	private PackStore cloneStore(PackStore source)
	{
		return gson.fromJson(gson.toJson(source), PackStore.class);
	}

	private Pack clonePack(Pack source)
	{
		return gson.fromJson(gson.toJson(source), Pack.class);
	}

	private PackStore emptyStore(String profileKey)
	{
		PackStore store = new PackStore();
		store.profileKey = sanitizeProfile(profileKey);
		return store;
	}

	private String sanitizeProfile(String profileKey)
	{
		String value = profileKey == null || profileKey.trim().isEmpty() ? "default" : profileKey.trim();
		return value.replaceAll("[^A-Za-z0-9._-]", "_");
	}
}

package com.packcheck.service;

import com.packcheck.model.ExtraItemMode;
import com.packcheck.model.MatchOption;
import com.packcheck.model.Pack;
import com.packcheck.model.PackComposition;
import com.packcheck.model.PackConflict;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackResolution;
import com.packcheck.model.PackType;
import com.packcheck.model.ResolvedRequirement;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class PackResolver
{
	public PackResolution resolve(PackComposition composition, Collection<Pack> packs)
	{
		Map<String, Pack> byId = index(packs);
		if (composition == null || (composition.mainPackId == null && composition.equipmentPackId == null))
		{
			return new PackResolution("No pack selected", ExtraItemMode.IGNORE,
				new ArrayList<>(), new ArrayList<>());
		}

		Pack main = composition.mainPackId == null ? null : requirePack(byId, composition.mainPackId);
		if (main != null && main.type == PackType.EQUIPMENT)
		{
			throw new IllegalArgumentException(main.name + " is a Wear kit, not an inventory Pack");
		}
		List<ResolvedRequirement> combined = main == null ? new ArrayList<>()
			: new ArrayList<>(resolveSingle(main.id, byId));
		List<PackConflict> conflicts = new ArrayList<>();
		StringBuilder displayName = new StringBuilder(main == null ? "" : main.name);

		if (composition.equipmentPackId != null && !composition.equipmentPackId.equals(composition.mainPackId))
		{
			Pack equipment = requirePack(byId, composition.equipmentPackId);
			if (equipment.type != PackType.EQUIPMENT)
			{
				throw new IllegalArgumentException(equipment.name + " is not an equipment kit");
			}
			if (displayName.length() > 0)
			{
				displayName.append(" + ");
			}
			displayName.append(equipment.name);
			mergePack(combined, resolveSingle(equipment.id, byId), composition, conflicts);
		}

		for (String addOnId : composition.addOnPackIds)
		{
			Pack addOn = requirePack(byId, addOnId);
			if (!addOn.addOnEligible)
			{
				throw new IllegalArgumentException(addOn.name + " is not eligible as an add-on");
			}
			if (addOn.type == PackType.EQUIPMENT)
			{
				throw new IllegalArgumentException(addOn.name + " is a Wear kit, not a reusable add-on");
			}
			if (displayName.length() > 0)
			{
				displayName.append(" + ");
			}
			displayName.append(addOn.name);
			mergePack(combined, resolveSingle(addOn.id, byId), composition, conflicts);
		}

		ExtraItemMode extraItemMode = main == null ? ExtraItemMode.IGNORE : main.extraItemMode;
		return new PackResolution(displayName.toString(), extraItemMode, combined, conflicts);
	}

	public List<ResolvedRequirement> resolveSingle(String packId, Collection<Pack> packs)
	{
		return resolveSingle(packId, index(packs));
	}

	public void validateNoCycles(Collection<Pack> packs)
	{
		Map<String, Pack> byId = index(packs);
		for (Pack pack : packs)
		{
			resolveSingle(pack.id, byId);
		}
	}

	private List<ResolvedRequirement> resolveSingle(String packId, Map<String, Pack> byId)
	{
		return resolveSingle(packId, byId, new ArrayDeque<>());
	}

	private List<ResolvedRequirement> resolveSingle(String packId, Map<String, Pack> byId, Deque<String> path)
	{
		if (path.contains(packId))
		{
			path.addLast(packId);
			throw new IllegalArgumentException("Pack inheritance cycle: " + String.join(" -> ", path));
		}

		Pack pack = requirePack(byId, packId);
		path.addLast(packId);
		LinkedHashMap<String, ResolvedRequirement> resolved = new LinkedHashMap<>();
		if (pack.basePackId != null && !pack.basePackId.trim().isEmpty())
		{
			for (ResolvedRequirement inherited : resolveSingle(pack.basePackId, byId, path))
			{
				resolved.put(inherited.requirement.id, new ResolvedRequirement(
					inherited.requirement.copy(), inherited.sourcePackId, inherited.sourcePackName, true));
			}
		}

		for (PackRequirement requirement : pack.requirements)
		{
			if (requirement.id == null || requirement.id.trim().isEmpty())
			{
				throw new IllegalArgumentException("Pack " + pack.name + " contains a requirement without a stable id");
			}
			resolved.put(requirement.id, new ResolvedRequirement(requirement.copy(), pack.id, pack.name, false));
		}
		path.removeLast();
		return new ArrayList<>(resolved.values());
	}

	private void mergePack(List<ResolvedRequirement> combined, List<ResolvedRequirement> addOnRequirements,
		PackComposition composition, List<PackConflict> conflicts)
	{
		Map<String, Integer> indexes = new HashMap<>();
		for (int index = 0; index < combined.size(); index++)
		{
			indexes.put(combined.get(index).requirement.id, index);
		}

		for (ResolvedRequirement candidate : addOnRequirements)
		{
			Integer existingIndex = indexes.get(candidate.requirement.id);
			if (existingIndex == null)
			{
				indexes.put(candidate.requirement.id, combined.size());
				combined.add(candidate);
				continue;
			}

			ResolvedRequirement existing = combined.get(existingIndex);
			if (semanticallyEqual(existing.requirement, candidate.requirement))
			{
				continue;
			}

			String chosenSource = composition.conflictResolutions.get(candidate.requirement.id);
			if (Objects.equals(chosenSource, candidate.sourcePackId))
			{
				combined.set(existingIndex, candidate);
			}
			else if (!Objects.equals(chosenSource, existing.sourcePackId))
			{
				conflicts.add(new PackConflict(candidate.requirement.id, existing, candidate));
			}
		}
	}

	private boolean semanticallyEqual(PackRequirement first, PackRequirement second)
	{
		return Objects.equals(first.displayName, second.displayName)
			&& first.required == second.required
			&& first.enabled == second.enabled
			&& first.location == second.location
			&& first.measurement == second.measurement
			&& first.minimum == second.minimum
			&& Objects.equals(first.exact, second.exact)
			&& Objects.equals(first.maximum, second.maximum)
			&& Objects.equals(first.requiredEquipmentSlot, second.requiredEquipmentSlot)
			&& Objects.equals(first.fixedInventorySlot, second.fixedInventorySlot)
			&& Objects.equals(first.notes, second.notes)
			&& optionsEqual(first.alternatives, second.alternatives);
	}

	private boolean optionsEqual(List<MatchOption> first, List<MatchOption> second)
	{
		if (first.size() != second.size())
		{
			return false;
		}
		for (int index = 0; index < first.size(); index++)
		{
			MatchOption a = first.get(index);
			MatchOption b = second.get(index);
			if (!Objects.equals(a.label, b.label) || !Objects.equals(a.itemIds, b.itemIds)
				|| !Objects.equals(a.familyKey, b.familyKey) || a.matchVariations != b.matchVariations)
			{
				return false;
			}
		}
		return true;
	}

	private Map<String, Pack> index(Collection<Pack> packs)
	{
		Map<String, Pack> byId = new LinkedHashMap<>();
		for (Pack pack : packs)
		{
			if (pack.id == null || pack.id.trim().isEmpty())
			{
				throw new IllegalArgumentException("Pack without stable id");
			}
			if (byId.put(pack.id, pack) != null)
			{
				throw new IllegalArgumentException("Duplicate pack id: " + pack.id);
			}
		}
		return byId;
	}

	private Pack requirePack(Map<String, Pack> byId, String id)
	{
		Pack pack = byId.get(id);
		if (pack == null)
		{
			throw new IllegalArgumentException("Unknown pack id: " + id);
		}
		return pack;
	}
}

package com.packcheck.service;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Loads the offline, source-reviewed inventory research bundled with the plugin. */
final class ResearchPresetCatalog
{
	private static final String RESOURCE = "/com/packcheck/research-presets.tsv";

	List<Entry> load()
	{
		InputStream input = ResearchPresetCatalog.class.getResourceAsStream(RESOURCE);
		if (input == null)
		{
			throw new IllegalStateException("Missing built-in preset catalog " + RESOURCE);
		}

		List<Entry> entries = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(input, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#") || line.startsWith("key\t"))
				{
					continue;
				}
				String[] fields = line.split("\t", -1);
				if (fields.length != 13)
				{
					throw new IllegalStateException("Invalid built-in preset row: " + line);
				}
				entries.add(new Entry(fields));
			}
		}
		catch (IOException exception)
		{
			throw new IllegalStateException("Could not read built-in preset catalog", exception);
		}
		return Collections.unmodifiableList(entries);
	}

	static final class Entry
	{
		final String key;
		final String category;
		final String activity;
		final String method;
		final String potions;
		final String food;
		final String utilities;
		final int plannedSlots;
		final int switchSlots;
		final int lootSlots;
		final String confidence;
		final String sourceUrl;
		final String notes;

		private Entry(String[] fields)
		{
			key = fields[0];
			category = fields[1];
			activity = fields[2];
			method = fields[3];
			potions = fields[4];
			food = fields[5];
			utilities = fields[6];
			plannedSlots = parseSlots(fields[7]);
			switchSlots = parseSlots(fields[8]);
			lootSlots = parseSlots(fields[9]);
			confidence = fields[10];
			sourceUrl = fields[11];
			notes = fields[12];
			if (plannedSlots + switchSlots + lootSlots != 28)
			{
				throw new IllegalStateException(key + " does not account for 28 inventory slots");
			}
		}

		private static int parseSlots(String value)
		{
			try
			{
				return Integer.parseInt(value);
			}
			catch (NumberFormatException exception)
			{
				throw new IllegalStateException("Invalid inventory slot count " + value, exception);
			}
		}
	}
}

package com.packcheck.service;

import com.packcheck.model.LocationScope;
import com.packcheck.model.MatchOption;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.Pack;
import com.packcheck.model.PackRequirement;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/** Converts reviewed prose rows into stable item/dose rules and explicit manual checks. */
final class ResearchPresetRuleFactory
{
	private static final Pattern MULTIPLIER = Pattern.compile("×\\s*([0-9,]+)");
	private static final Pattern DOSE_SIZE = Pattern.compile("\\(([1-4])\\)");
	private static final Pattern TOTAL_DOSES = Pattern.compile("([0-9,]+)\\s*doses?", Pattern.CASE_INSENSITIVE);

	void populate(Pack pack, ResearchPresetCatalog.Entry entry)
	{
		List<PackRequirement> automatic = new ArrayList<>();
		List<String> manualFragments = new ArrayList<>();
		parsePotions(pack.presetKey, entry.potions, automatic, manualFragments);
		parseFood(pack.presetKey, entry.food, automatic, manualFragments);
		parseUtilities(pack.presetKey, entry.utilities, automatic, manualFragments);

		int automaticSlots = automatic.stream().filter(requirement -> requirement.required)
			.mapToInt(requirement -> requirement.recommendedSlots).sum();
		if (automaticSlots > entry.plannedSlots)
		{
			automatic.clear();
			manualFragments.clear();
			manualFragments.add(joinPlan(entry));
			automaticSlots = 0;
		}

		pack.requirements.addAll(automatic);
		int manualSlots = entry.plannedSlots - automaticSlots;
		if (!manualFragments.isEmpty() || manualSlots > 0)
		{
			String plan = manualFragments.isEmpty() ? joinPlan(entry) : String.join("; ", manualFragments);
			pack.requirements.add(manual(pack.presetKey, "manual_inventory", "Manual inventory check",
				manualSlots, plan, "Confirm the remaining carried utilities or player-specific alternatives. "
					+ "You can replace this with exact item-ID rules after installing the preset."));
		}

		if (containsRunePouch(entry.utilities))
		{
			pack.requirements.add(manual(pack.presetKey, "manual_rune_pouch", "Rune pouch contents",
				0, "Confirm the runes required by this method",
				"PackCheck can see the pouch itself but cannot reliably inspect its contents."));
		}
	}

	private void parsePotions(String key, String text, List<PackRequirement> automatic, List<String> manual)
	{
		for (String segment : segments(text))
		{
			String[][] families = doseFamilies(segment);
			if (families == null)
			{
				manual.add(segment);
				continue;
			}
			int doses = totalDoses(segment);
			int bottles = bottleCount(segment, doses);
			PackRequirement requirement = requirement(key, "potion_" + automatic.size(), cleanLabel(segment),
				MeasurementType.TOTAL_DOSES, doses, bottles, segment,
				"Partial bottles and compatible alternatives are pooled by total dose count.");
			for (String[] family : families)
			{
				requirement.alternatives.add(MatchOption.family(family[0], family[1]));
			}
			automatic.add(requirement);
		}
	}

	private void parseFood(String key, String text, List<PackRequirement> automatic, List<String> manual)
	{
		for (String segment : segments(text))
		{
			int[] ids = foodIds(segment);
			if (ids == null)
			{
				manual.add(segment);
				continue;
			}
			int quantity = multiplier(segment, 1);
			PackRequirement requirement = requirement(key, "food_" + automatic.size(), cleanLabel(segment),
				MeasurementType.ITEM_QUANTITY, quantity, quantity, segment,
				"This checks food carried in the inventory, never the worn combat setup.");
			requirement.alternatives.add(exact(cleanLabel(segment), ids));
			automatic.add(requirement);
		}
	}

	private void parseUtilities(String key, String text, List<PackRequirement> automatic, List<String> manual)
	{
		for (String segment : segments(text))
		{
			int[] ids = utilityIds(segment);
			if (ids == null)
			{
				manual.add(segment);
				continue;
			}
			int quantity = utilityQuantity(segment);
			int slots = isStack(segment) ? 1 : quantity;
			PackRequirement requirement = requirement(key, "utility_" + automatic.size(), cleanLabel(segment),
				MeasurementType.ITEM_QUANTITY, quantity, slots, segment,
				"Checked as carried inventory. Equippable route items are not advice about what to wear.");
			requirement.alternatives.add(exact(cleanLabel(segment), ids));
			automatic.add(requirement);
		}
	}

	private String[][] doseFamilies(String segment)
	{
		String value = normalize(segment);
		if (value.contains("prayer/stat restoration") || value.contains("prayer restoration")
			|| value.contains("prayer-restoration") || value.contains("prayer/restoration"))
		{
			return families("prayer_potion", "Prayer potion", "super_restore", "Super restore",
				"sanfew_serum", "Sanfew serum");
		}
		if (value.contains("ranged boost"))
		{
			return families("ranging", "Ranging potion", "divine_ranging", "Divine ranging potion",
				"bastion", "Bastion potion", "divine_bastion", "Divine bastion potion");
		}
		String[][] aliases = {
			{"extended anti-venom+", "extended_antivenom_plus", "Extended anti-venom+"},
			{"anti-venom+", "antivenom_plus", "Anti-venom+"},
			{"anti-venom", "antivenom", "Anti-venom"},
			{"antidote++", "antidote_plus_plus", "Antidote++"},
			{"extended super antifire", "extended_super_antifire", "Extended super antifire"},
			{"super antifire", "super_antifire", "Super antifire"},
			{"extended antifire", "extended_antifire", "Extended antifire"},
			{"antifire", "antifire", "Antifire potion"},
			{"divine super combat", "divine_super_combat", "Divine super combat"},
			{"super combat", "super_combat", "Super combat potion"},
			{"divine ranging", "divine_ranging", "Divine ranging potion"},
			{"ranging potion", "ranging", "Ranging potion"},
			{"divine bastion", "divine_bastion", "Divine bastion potion"},
			{"bastion", "bastion", "Bastion potion"},
			{"super strength", "super_strength", "Super strength"},
			{"super attack", "super_attack", "Super attack"},
			{"super defence", "super_defence", "Super defence"},
			{"prayer regeneration", "prayer_regeneration", "Prayer regeneration potion"},
			{"prayer potion", "prayer_potion", "Prayer potion"},
			{"blighted super restore", "blighted_super_restore", "Blighted super restore"},
			{"super restore", "super_restore", "Super restore"},
			{"sanfew serum", "sanfew_serum", "Sanfew serum"},
			{"sanfew", "sanfew_serum", "Sanfew serum"},
			{"armadyl brew", "armadyl_brew", "Armadyl brew"},
			{"saradomin brew", "saradomin_brew", "Saradomin brew"},
			{"brew", "saradomin_brew", "Saradomin brew"},
			{"guthix rest", "guthix_rest", "Guthix rest"},
			{"goading", "goading", "Goading potion"},
			{"stamina", "stamina", "Stamina potion"},
			{"energy potion", "energy", "Energy potion"},
			{"antipoison", "antipoison", "Antipoison"},
			{"moonlight potion", "moonlight", "Moonlight potion"},
			{"surge potion", "surge", "Surge potion"},
		};
		for (String[] alias : aliases)
		{
			if (value.contains(alias[0]))
			{
				return families(alias[1], alias[2]);
			}
		}
		return null;
	}

	private int[] foodIds(String segment)
	{
		String value = normalize(segment);
		if (value.contains("high-heal food") || value.startsWith("food "))
		{
			return new int[]{ItemID.SHARK, ItemID.MANTARAY, ItemID.ANGLERFISH, ItemID.DARK_CRAB,
				ItemID.MONKFISH, ItemID.POTATO_TUNA_SWEETCORN};
		}
		if (value.contains("blighted manta")) return new int[]{ItemID.BLIGHTED_MANTARAY};
		if (value.contains("manta")) return new int[]{ItemID.MANTARAY};
		if (value.contains("karambwan")) return new int[]{ItemID.TBWT_COOKED_KARAMBWAN};
		if (value.contains("anglerfish")) return new int[]{ItemID.ANGLERFISH};
		if (value.contains("shark")) return new int[]{ItemID.SHARK};
		if (value.contains("dark crab")) return new int[]{ItemID.DARK_CRAB};
		if (value.contains("monkfish")) return new int[]{ItemID.MONKFISH};
		if (value.contains("tuna potato")) return new int[]{ItemID.POTATO_TUNA_SWEETCORN};
		if (value.contains("summer pie")) return new int[]{ItemID.SUMMER_PIE};
		if (value.contains("trout")) return new int[]{ItemID.TROUT};
		if (value.contains("moonlight antelope")) return new int[]{ItemID.ANTELOPEMOON_COOKED};
		if (value.contains("sunlight antelope")) return new int[]{ItemID.ANTELOPESUN_COOKED};
		if (value.contains("halibut")) return new int[]{ItemID.HALIBUT};
		return null;
	}

	private int[] utilityIds(String segment)
	{
		String value = normalize(segment);
		if (value.contains("rune pouch"))
		{
			return new int[]{ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER,
				ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER};
		}
		if (value.equals("house teleport")) return new int[]{ItemID.POH_TABLET_TELEPORTTOHOUSE};
		if (value.contains("royal seed pod")) return new int[]{ItemID.MM2_ROYAL_SEED_POD};
		if (value.equals("spade")) return new int[]{ItemID.SPADE};
		if (value.contains("herb sack")) return new int[]{ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_OPEN};
		if (value.contains("holy wrench")) return new int[]{ItemID.DEAL_WRENCH_BLESSED};
		if (value.contains("book of the dead")) return new int[]{ItemID.BOOK_OF_THE_DEAD};
		if (value.contains("looting bag")) return new int[]{ItemID.LOOTING_BAG, ItemID.LOOTING_BAG_OPEN};
		if (value.contains("cannonballs")) return new int[]{ItemID.MCANNONBALL, ItemID.GRANITE_CANNONBALL};
		if (value.contains("death runes")) return new int[]{ItemID.DEATHRUNE};
		if (value.contains("giant key")) return new int[]{ItemID.HILLGIANT_BOSS_KEY};
		if (value.contains("mossy key")) return new int[]{ItemID.MOSSY_KEY};
		return null;
	}

	private PackRequirement requirement(String key, String suffix, String name, MeasurementType measurement,
		int minimum, int slots, String recommendation, String notes)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.id = key + ":" + suffix;
		requirement.displayName = name;
		requirement.location = LocationScope.INVENTORY_ONLY;
		requirement.measurement = measurement;
		requirement.minimum = minimum;
		requirement.recommendedSlots = slots;
		requirement.recommendation = recommendation;
		requirement.notes = notes;
		return requirement;
	}

	private PackRequirement manual(String key, String suffix, String name, int slots, String recommendation,
		String notes)
	{
		return requirement(key, suffix, name, MeasurementType.MANUAL_CONFIRMATION, 1, slots,
			recommendation, notes);
	}

	private MatchOption exact(String label, int... ids)
	{
		MatchOption option = new MatchOption();
		option.label = label;
		for (int id : ids)
		{
			option.itemIds.add(id);
		}
		return option;
	}

	private List<String> segments(String text)
	{
		if (text == null || text.trim().isEmpty() || "none".equalsIgnoreCase(text.trim()))
		{
			return Collections.emptyList();
		}
		List<String> values = new ArrayList<>();
		for (String segment : text.split(";"))
		{
			if (!segment.trim().isEmpty())
			{
				values.add(segment.trim());
			}
		}
		return values;
	}

	private int totalDoses(String segment)
	{
		Matcher total = TOTAL_DOSES.matcher(segment);
		if (total.find())
		{
			return number(total.group(1));
		}
		int bottles = multiplier(segment, 1);
		Matcher doseSize = DOSE_SIZE.matcher(segment);
		int perBottle = doseSize.find() ? Integer.parseInt(doseSize.group(1)) : 4;
		return bottles * perBottle;
	}

	private int bottleCount(String segment, int doses)
	{
		Matcher total = TOTAL_DOSES.matcher(segment);
		return total.find() ? (doses + 3) / 4 : multiplier(segment, 1);
	}

	private int utilityQuantity(String segment)
	{
		String value = normalize(segment);
		return value.contains("cannonballs") || value.contains("death runes")
			? multiplier(segment, 1) : 1;
	}

	private boolean isStack(String segment)
	{
		String value = normalize(segment);
		return value.contains("stack") || value.contains("cannonballs") || value.contains("runes");
	}

	private int multiplier(String segment, int fallback)
	{
		Matcher matcher = MULTIPLIER.matcher(segment);
		return matcher.find() ? number(matcher.group(1)) : fallback;
	}

	private int number(String value)
	{
		return Integer.parseInt(value.replace(",", ""));
	}

	private String cleanLabel(String segment)
	{
		return segment.replaceAll("\\s*×\\s*[0-9,]+.*$", "")
			.replaceAll("\\([1-4]\\)", "").replaceAll(":\\s*[0-9,]+\\s*doses?", "")
			.trim();
	}

	private String normalize(String value)
	{
		return value.toLowerCase(Locale.ENGLISH).replace('’', '\'').trim();
	}

	private boolean containsRunePouch(String value)
	{
		return value != null && normalize(value).contains("rune pouch");
	}

	private String joinPlan(ResearchPresetCatalog.Entry entry)
	{
		return String.join("; ", Arrays.asList(entry.potions, entry.food, entry.utilities));
	}

	private String[][] families(String... keyLabels)
	{
		String[][] values = new String[keyLabels.length / 2][2];
		for (int index = 0; index < keyLabels.length; index += 2)
		{
			values[index / 2][0] = keyLabels[index];
			values[index / 2][1] = keyLabels[index + 1];
		}
		return values;
	}
}

package com.packcheck.service;

import com.packcheck.model.ItemStackSnapshot;
import com.packcheck.model.PackSnapshot;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

/** Reads client containers. Call only from the RuneLite client thread. */
public class SnapshotService
{
	private final Client client;
	private final ItemManager itemManager;

	@Inject
	public SnapshotService(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	public PackSnapshot capture()
	{
		return new PackSnapshot(read(InventoryID.INV), read(InventoryID.WORN));
	}

	private List<ItemStackSnapshot> read(int inventoryId)
	{
		List<ItemStackSnapshot> snapshot = new ArrayList<>();
		ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return snapshot;
		}
		Item[] items = container.getItems();
		for (int slot = 0; slot < items.length; slot++)
		{
			Item item = items[slot];
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			ItemComposition composition = itemManager.getItemComposition(item.getId());
			String name = composition == null ? "Item " + item.getId() : composition.getName();
			snapshot.add(new ItemStackSnapshot(item.getId(), Math.max(1, item.getQuantity()), slot, name));
		}
		return snapshot;
	}
}

