	private JPanel createActions()
	{
		JPanel actions = new JPanel(new GridLayout(2, 2, 5, 5));
		actions.setOpaque(false);
		PackCheckTheme.primary(smartPresets);
		PackCheckTheme.secondary(captureSetup);
		PackCheckTheme.secondary(editPack);
		PackCheckTheme.secondary(moreActions);

		smartPresets.addActionListener(event -> showPresets());
		captureSetup.addActionListener(event ->
		{
			Object[] modes = {"Pack - inventory", "Wear - equipped gear", "Trip - both", "Cancel"};
			int mode = JOptionPane.showOptionDialog(this,
				"What should this saved checklist capture?",
				"Capture current setup", JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE,
				null, modes, modes[0]);
			if (mode < 0 || mode == 3)
			{
				return;
			}
			PackType type = mode == 0 ? PackType.INVENTORY : mode == 1 ? PackType.EQUIPMENT : PackType.TRIP;
			String name = JOptionPane.showInputDialog(this, "Name this "
				+ (type == PackType.EQUIPMENT ? "gear kit" : type == PackType.TRIP ? "trip" : "inventory pack"),
				"Capture current setup", JOptionPane.PLAIN_MESSAGE);
			if (name != null && !name.trim().isEmpty())
			{
				controller.capturePack(name.trim(), type);
			}
		});
		editPack.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected != null)
			{
				Pack edited = PackEditorDialog.edit(this, selected, store.packs);
				if (edited != null)
				{
					controller.savePack(edited);
				}
			}
		});

		createCustom.addActionListener(event ->
		{
			Pack pack = PackEditorDialog.edit(this, new Pack(), store.packs);
			if (pack != null)
			{
				controller.savePack(pack);
			}
		});
		duplicatePack.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected != null)
			{
				controller.duplicatePack(selected.id);
			}
		});
		renamePack.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected != null)
			{
				String name = JOptionPane.showInputDialog(this, "New pack name", selected.name);
				if (name != null && !name.trim().isEmpty())
				{
					Pack renamed = selected.copy();
					renamed.name = name.trim();
					controller.savePack(renamed);
				}
			}
		});
		defaultPack.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected != null)
			{
				controller.setDefaultPack(selected.id);
			}
		});
		resetPreset.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected == null || selected.presetKey == null)
			{
				return;
			}
			boolean update = hasPresetUpdate(selected);
			String title = update ? "Update preset" : "Reset preset";
			String prompt = update
				? "Install the latest built-in plan for \"" + selected.name
					+ "\" and replace every customization?\n\n" + controller.presetChangeSummary(selected.id)
				: "Replace every customization in \"" + selected.name
					+ "\" with the current built-in defaults?\n\n" + controller.presetChangeSummary(selected.id);
			if (JOptionPane.showConfirmDialog(this,
				prompt, title, JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION)
			{
				controller.resetPreset(selected.id);
			}
		});
		deletePack.addActionListener(event ->
		{
			Pack selected = selectedPack();
			if (selected != null && JOptionPane.showConfirmDialog(this,
				"Delete \"" + selected.name + "\"?", "Delete pack", JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION)
			{
				controller.deletePack(selected.id);
			}
		});
		resolveConflict.addActionListener(event -> resolveFirstConflict());
		importPacks.addActionListener(event -> showImport());
		exportPacks.addActionListener(event -> showExport());

		moreActions.addActionListener(event ->
		{
			updateActionAvailability();
			showActionSheet();
		});

		actions.add(smartPresets);
		actions.add(captureSetup);
		actions.add(editPack);
		actions.add(moreActions);
		return actions;
	}

	private void showActionSheet()
	{
		JMenuItem[] allActions = {duplicatePack, renamePack, defaultPack, resetPreset, resolveConflict,
			createCustom, importPacks, exportPacks, deletePack};
		DefaultListModel<JMenuItem> model = new DefaultListModel<>();
		for (JMenuItem action : allActions)
		{
			if (action.isEnabled())
			{
				model.addElement(action);
			}
		}
		JList<JMenuItem> choices = new JList<>(model);
		choices.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		choices.setSelectedIndex(0);
		choices.setFixedCellHeight(34);
		choices.setVisibleRowCount(Math.min(8, model.size()));
		choices.setCellRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean selected, boolean focused)
			{
				JMenuItem action = (JMenuItem) value;
				Component component = super.getListCellRendererComponent(list, action.getText(), index, selected, focused);
				component.setForeground(selected ? Color.WHITE
					: action == deletePack ? PackCheckTheme.MISSING : PackCheckTheme.TEXT);
				return component;
			}
		});

		Pack selected = selectedPack();
		String subject = selected == null ? "PackCheck" : compactName(selected.name);
		JPanel content = new JPanel(new BorderLayout(0, 7));
		content.setPreferredSize(new Dimension(310, Math.min(300, model.size() * 34 + 32)));
		content.add(new JLabel("Manage " + subject), BorderLayout.NORTH);
		content.add(new JScrollPane(choices), BorderLayout.CENTER);
		int result = JOptionPane.showConfirmDialog(this, content, "Pack actions",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (result == JOptionPane.OK_OPTION && choices.getSelectedValue() != null)
		{
			choices.getSelectedValue().doClick();
		}
	}

	private void showGearActions()
	{
		Pack gear = gearList.getSelectedValue();
		Object[] actions = gear == null
			? new Object[]{"Clear active gear", "Cancel"}
			: new Object[]{"Edit kit", "Duplicate kit", "Delete kit", "Clear active gear", "Cancel"};
		int choice = JOptionPane.showOptionDialog(this,
			gear == null ? "No gear kit is selected." : "Manage " + compactName(gear.name),
			"Wear kit actions", JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, actions, actions[0]);
		if (gear == null)
		{
			if (choice == 0)
			{
				controller.selectEquipmentPack(null);
			}
			return;
		}
		if (choice == 0)
		{
			Pack edited = PackEditorDialog.edit(this, gear, store.packs);
			if (edited != null)
			{
				controller.savePack(edited);
			}
		}
		else if (choice == 1)
		{
			controller.duplicatePack(gear.id);
		}
		else if (choice == 2 && JOptionPane.showConfirmDialog(this,
			"Delete gear kit \"" + gear.name + "\"?", "Delete gear kit",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION)
		{
			controller.deletePack(gear.id);
		}
		else if (choice == 3)
		{
			controller.selectEquipmentPack(null);
		}
	}

