	private void showExport()
	{
		Object[] choices = {"Shareable encoded string", "JSON"};
		int choice = JOptionPane.showOptionDialog(this, "Choose an export format. Pack data stays local unless you copy it.",
			"Export packs", JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, choices, choices[0]);
