	private void showImport()
	{
		JTextArea text = new JTextArea(18, 55);
		int result = JOptionPane.showConfirmDialog(this, new JScrollPane(text), "Paste PackCheck JSON or encoded string",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (result != JOptionPane.OK_OPTION)
		{
			return;
		}
		try
		{
			ImportPreview preview = controller.previewImport(text.getText());
			Object[] choices = {"Merge", "Replace all", "Cancel"};
			int choice = JOptionPane.showOptionDialog(this, preview.summary,
				"Import preview", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
				null, choices, choices[0]);
			if (choice == 0 || choice == 1)
			{
				controller.applyImport(preview, choice == 1);
			}
		}
		catch (RuntimeException exception)
		{
			JOptionPane.showMessageDialog(this, exception.getMessage(), "Import failed", JOptionPane.ERROR_MESSAGE);
		}
	}

	private void resolveFirstConflict()
	{
		if (resolution == null || resolution.conflicts.isEmpty())
		{
			return;
		}
		PackConflict conflict = resolution.conflicts.get(0);
		Object[] choices = {conflict.first.sourcePackName, conflict.second.sourcePackName};
		int choice = JOptionPane.showOptionDialog(this,
			"\"" + conflict.first.requirement.displayName + "\" differs between packs. Choose the supplier:",
			"Pack conflict", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
			null, choices, choices[0]);
		if (choice == 0)
		{
			controller.resolveConflict(conflict.requirementId, conflict.first.sourcePackId);
		}
		else if (choice == 1)
		{
			controller.resolveConflict(conflict.requirementId, conflict.second.sourcePackId);
		}
	}

	private void rebuildPackList()
	{
		updating = true;
		try
		{
			String query = search.getText().trim().toLowerCase(Locale.ENGLISH);
			packModel.clear();
			for (Pack pack : store.packs)
			{
				if (pack.type != PackType.EQUIPMENT && (query.isEmpty()
					|| pack.name.toLowerCase(Locale.ENGLISH).contains(query)
					|| (pack.presetMethod != null && pack.presetMethod.toLowerCase(Locale.ENGLISH).contains(query))))
				{
					packModel.addElement(pack);
				}
			}
			if (store.composition.mainPackId != null)
			{
				for (int index = 0; index < packModel.size(); index++)
				{
					if (store.composition.mainPackId.equals(packModel.get(index).id))
					{
						packList.setSelectedIndex(index);
						break;
					}
				}
			}
		}
		finally
		{
			updating = false;
		}
	}

	private void rebuildGearList()
	{
		updating = true;
		try
		{
			gearModel.clear();
			for (Pack pack : store.packs)
			{
				if (pack.type == PackType.EQUIPMENT)
				{
					gearModel.addElement(pack);
				}
			}
			for (int index = 0; index < gearModel.size(); index++)
			{
				if (gearModel.get(index).id.equals(store.composition.equipmentPackId))
				{
					gearList.setSelectedIndex(index);
					break;
				}
			}
			gearActions.setEnabled(!gearModel.isEmpty() || store.composition.equipmentPackId != null);
		}
		finally
		{
			updating = false;
		}
	}

	private void rebuildAddOns()
	{
		addOnModel.clear();
		List<Integer> selectedIndexes = new ArrayList<>();
		for (Pack pack : store.packs)
		{
			if (pack.type != PackType.EQUIPMENT && pack.addOnEligible
				&& !pack.id.equals(store.composition.mainPackId))
			{
				int index = addOnModel.size();
				addOnModel.addElement(pack);
				if (store.composition.addOnPackIds.contains(pack.id))
				{
					selectedIndexes.add(index);
				}
			}
		}
		addOnList.setSelectedIndices(selectedIndexes.stream().mapToInt(Integer::intValue).toArray());
	}

	private void updateSummary()
	{
		Pack selected = selectedPack();
		Pack selectedGear = selectedEquipmentPack();
		workspaceLayout.show(workspace, store.packs.isEmpty() ? "onboarding" : "active");
		updateActionAvailability();
		updateProgress();
		if (selected == null && selectedGear == null)
		{
			setStatus("GET STARTED", new Color(255, 215, 140), PackCheckTheme.ACCENT_DARK);
			method.setText(store.packs.isEmpty() ? "Pick a plan or capture setup" : "Select a pack to continue");
			method.setToolTipText(null);
			counts.setText(store.packs.isEmpty() ? "No active checklist" : store.packs.size() + " packs available");
			plan.setText("");
			composition.setText("");
			composition.setVisible(false);
			updateEvaluation();
			return;
		}

		Pack headingPack = selected == null ? selectedGear : selected;
		method.setText(compactName(headingPack.name));
		method.setToolTipText((headingPack.presetMethod == null ? "" : headingPack.presetMethod)
			+ (headingPack.presetPlanNotes == null || headingPack.presetPlanNotes.isEmpty()
				? "" : " - " + headingPack.presetPlanNotes));
		counts.setText("PACK " + latestEvaluation.satisfiedInventoryChecks() + "/"
			+ latestEvaluation.totalInventoryChecks() + "   WEAR "
			+ latestEvaluation.satisfiedEquipmentChecks() + "/" + latestEvaluation.totalEquipmentChecks()
			+ "   CHECK " + latestEvaluation.satisfiedManualChecks() + "/"
			+ latestEvaluation.totalManualChecks());
		counts.setToolTipText(latestEvaluation.requiredFailureCount() + " required issue(s), "
			+ latestEvaluation.warningCount() + " warning(s)");
		plan.setText(selected == null ? "Gear-only readiness"
			: selected.recommendedInventorySlots + " checked  |  " + selected.switchInventorySlots
				+ " switch  |  " + selected.lootInventorySlots + " loot/flex");

		String baseName = baseName(selected);
		String addOnNames = activeAddOnNames();
		String context = selectedGear == null ? "" : "Wear: " + compactName(selectedGear.name);
		if (!"none".equals(baseName))
		{
			context += (context.isEmpty() ? "" : "  |  ") + "Base: " + baseName;
		}
		if (!"none".equals(addOnNames))
		{
			context += (context.isEmpty() ? "" : "  |  ") + "Add-ons: " + addOnNames;
		}
		composition.setText(context);
		composition.setVisible(!context.isEmpty());

		if (resolution != null && !resolution.conflicts.isEmpty())
		{
			setStatus("CONFLICT", new Color(255, 216, 145), PackCheckTheme.WARNING_DARK);
			readiness.setForeground(PackCheckTheme.WARNING);
		}
		else if (latestEvaluation.ready && latestEvaluation.warningCount() == 0)
		{
			setStatus("READY TO GO", new Color(166, 231, 172), PackCheckTheme.READY_DARK);
			readiness.setForeground(PackCheckTheme.READY);
		}
		else if (latestEvaluation.ready)
		{
			setStatus("READY - REVIEW", new Color(255, 216, 145), PackCheckTheme.WARNING_DARK);
			readiness.setForeground(PackCheckTheme.WARNING);
		}
		else
		{
			boolean inventoryFailure = latestEvaluation.results.stream().anyMatch(result ->
				result.isRequiredFailure()
					&& result.resolvedRequirement.requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
					&& result.resolvedRequirement.requirement.location != com.packcheck.model.LocationScope.EQUIPMENT_ONLY);
			boolean equipmentFailure = latestEvaluation.results.stream().anyMatch(result ->
				result.isRequiredFailure()
					&& result.resolvedRequirement.requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
					&& result.resolvedRequirement.requirement.location == com.packcheck.model.LocationScope.EQUIPMENT_ONLY);
			if (inventoryFailure)
			{
				setStatus("PACKING", new Color(255, 177, 177), PackCheckTheme.MISSING_DARK);
				readiness.setForeground(PackCheckTheme.MISSING);
			}
			else if (equipmentFailure)
			{
				setStatus("GEARING UP", new Color(255, 177, 177), PackCheckTheme.MISSING_DARK);
				readiness.setForeground(PackCheckTheme.MISSING);
			}
			else
			{
				setStatus("CHECK DETAILS", new Color(255, 216, 145), PackCheckTheme.WARNING_DARK);
				readiness.setForeground(PackCheckTheme.WARNING);
			}
		}
		updateEvaluation();
	}

	private void setStatus(String text, Color foreground, Color background)
	{
		status.setText(text);
		status.setForeground(foreground);
		status.setBackground(background);
	}

	private void updateActionAvailability()
	{
		Pack selected = selectedPack();
		boolean hasSelection = selected != null;
		boolean conflict = resolution != null && !resolution.conflicts.isEmpty();
		editPack.setEnabled(hasSelection);
		duplicatePack.setEnabled(hasSelection);
		renamePack.setEnabled(hasSelection);
		defaultPack.setEnabled(hasSelection);
		deletePack.setEnabled(hasSelection);
		resetPreset.setEnabled(hasSelection && selected.presetKey != null);
		resetPreset.setText(hasPresetUpdate(selected) ? "Update to latest preset" : "Reset preset to defaults");
		resolveConflict.setEnabled(conflict);
		exportPacks.setEnabled(!store.packs.isEmpty());
	}

	private void updateEvaluation()
	{
		int previousScroll = evaluationScroll.getVerticalScrollBar().getValue();
		evaluationList.removeAll();
		Pack selected = selectedPack();
		if (selected == null && selectedEquipmentPack() == null)
		{
			addEvaluationCard(createMessageCard("SELECT A CHECKLIST",
				"Choose a Pack or Wear kit to start live trip readiness.", PackCheckTheme.ACCENT));
			finishEvaluationUpdate(previousScroll);
			return;
		}
		int shown = 0;
		for (RequirementResult result : latestEvaluation.results)
		{
			if (!selectedFilter().includes(result))
			{
				continue;
			}
			addEvaluationCard(createResultCard(result));
			shown++;
		}
		if (selectedFilter() != ResultFilter.READY)
		{
			for (RequirementResult extra : latestEvaluation.extras)
			{
				addEvaluationCard(createResultCard(extra));
				shown++;
			}
		}
		if (resolution != null && selectedFilter() != ResultFilter.READY)
		{
			for (PackConflict conflict : resolution.conflicts)
			{
				addEvaluationCard(createMessageCard("CONFLICT  |  " + conflict.first.requirement.displayName,
					conflict.first.sourcePackName + " vs " + conflict.second.sourcePackName
						+ ". Use More to choose which pack wins.", PackCheckTheme.WARNING));
				shown++;
			}
		}
		if (shown == 0)
		{
			addEvaluationCard(createMessageCard("ALL CLEAR HERE",
				"No checks match this filter.", PackCheckTheme.READY));
		}
		finishEvaluationUpdate(previousScroll);
	}

	private JPanel createResultCard(RequirementResult result)
	{
		Color accent = statusAccent(result.status);
		JPanel card = new JPanel(new BorderLayout(0, 6));
		card.setOpaque(true);
		card.setBackground(PackCheckTheme.SURFACE);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 1, 0, PackCheckTheme.BORDER),
				BorderFactory.createEmptyBorder(8, 8, 9, 8))));

		JPanel heading = new JPanel(new BorderLayout(6, 0));
		heading.setOpaque(false);
		JLabel state = new JLabel(statusLabel(result.status));
		state.setForeground(accent);
		state.setFont(state.getFont().deriveFont(Font.BOLD, 12f));
		heading.add(state, BorderLayout.WEST);
		JLabel scope = new JLabel(resultScopeLabel(result));
		scope.setOpaque(true);
		scope.setBackground(PackCheckTheme.SURFACE_RAISED);
		scope.setForeground(PackCheckTheme.MUTED);
		scope.setFont(scope.getFont().deriveFont(Font.BOLD, 11f));
		scope.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5));
		heading.add(scope, BorderLayout.EAST);
		card.add(heading, BorderLayout.NORTH);

		JPanel body = new JPanel();
		body.setOpaque(false);
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		JLabel name = wrappedLabel(result.resolvedRequirement.requirement.displayName,
			PackCheckTheme.TEXT, Font.BOLD, 15f);
		body.add(name);
		body.add(Box.createVerticalStrut(3));
		JLabel now = wrappedLabel(result.detail, result.status == RequirementStatus.SATISFIED
			? PackCheckTheme.READY : PackCheckTheme.TEXT, Font.PLAIN, 13f);
		body.add(now);

		String recommendation = result.resolvedRequirement.requirement.recommendation;
		if (recommendation != null && !recommendation.isEmpty())
		{
			body.add(Box.createVerticalStrut(4));
			body.add(wrappedLabel("Bring: " + recommendation, new Color(235, 181, 84), Font.PLAIN, 12f));
		}
		if (result.resolvedRequirement.requirement.measurement == MeasurementType.MANUAL_CONFIRMATION)
		{
			boolean confirmed = result.status == RequirementStatus.SATISFIED;
			body.add(Box.createVerticalStrut(7));
			JButton confirmation = new JButton(confirmed ? "Confirmed - click to clear" : "Confirm for this trip");
			PackCheckTheme.secondary(confirmation);
			confirmation.setAlignmentX(Component.LEFT_ALIGNMENT);
			confirmation.setMaximumSize(new Dimension(Integer.MAX_VALUE, confirmation.getPreferredSize().height));
			String requirementId = result.resolvedRequirement.requirement.id;
			confirmation.addActionListener(event -> controller.setManualCheck(requirementId, !confirmed));
			body.add(confirmation);
		}
		card.add(body, BorderLayout.CENTER);

		List<String> context = new ArrayList<>();
		if (result.resolvedRequirement.inherited)
		{
			context.add("Inherited from " + result.resolvedRequirement.sourcePackName);
		}
		if (!result.satisfyingAlternatives.isEmpty())
		{
			context.add("Matched: " + String.join(", ", result.satisfyingAlternatives));
		}
		String notes = result.resolvedRequirement.requirement.notes;
		if (notes != null && !notes.isEmpty())
		{
			context.add(notes);
		}
		if (!context.isEmpty())
		{
			card.setToolTipText("<html>" + context.stream().map(this::escape)
				.collect(Collectors.joining("<br>")) + "</html>");
		}
		return card;
	}

	private JPanel createMessageCard(String title, String message, Color accent)
	{
		JPanel card = new JPanel(new BorderLayout(0, 5));
		card.setOpaque(true);
		card.setBackground(PackCheckTheme.SURFACE);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 1, 0, PackCheckTheme.BORDER),
				BorderFactory.createEmptyBorder(9, 9, 10, 9))));
		JLabel heading = wrappedLabel(title, accent, Font.BOLD, 12f);
		JLabel detail = wrappedLabel(message, PackCheckTheme.TEXT, Font.PLAIN, 13f);
		card.add(heading, BorderLayout.NORTH);
		card.add(detail, BorderLayout.CENTER);
		return card;
	}

	private JLabel wrappedLabel(String text, Color color, int style, float size)
	{
		JLabel label = new JLabel("<html><body style='width:150px'>" + escape(text) + "</body></html>");
		label.setForeground(color);
		label.setFont(label.getFont().deriveFont(style, size));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private void addEvaluationCard(JPanel card)
	{
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		evaluationList.add(card);
		evaluationList.add(Box.createVerticalStrut(5));
	}

	private void finishEvaluationUpdate(int previousScroll)
	{
		evaluationList.revalidate();
		evaluationList.repaint();
		SwingUtilities.invokeLater(() ->
		{
			int maximum = evaluationScroll.getVerticalScrollBar().getMaximum()
				- evaluationScroll.getVerticalScrollBar().getVisibleAmount();
			evaluationScroll.getVerticalScrollBar().setValue(Math.min(previousScroll, Math.max(0, maximum)));
		});
	}

	private String resultScopeLabel(RequirementResult result)
	{
		if (result.resolvedRequirement.requirement.measurement == MeasurementType.MANUAL_CONFIRMATION)
		{
			return "CHECK";
		}
		return result.resolvedRequirement.requirement.location == LocationScope.EQUIPMENT_ONLY ? "WEAR" : "PACK";
	}

	private void updateProgress()
	{
		int total = 0;
		int satisfied = 0;
		for (RequirementResult result : latestEvaluation.results)
		{
			if (result.resolvedRequirement.requirement.required && result.status != RequirementStatus.IGNORED)
			{
				total++;
				satisfied += result.status == RequirementStatus.SATISFIED ? 1 : 0;
			}
		}
		readiness.setMaximum(Math.max(1, total));
		readiness.setValue(satisfied);
		score.setText(total == 0 ? "0 / 0 COMPLETE" : satisfied + " / " + total + " COMPLETE");
	}

	private boolean hasPresetUpdate(Pack selected)
	{
		if (selected == null || selected.presetKey == null)
		{
			return false;
		}
		for (PresetSummary preset : controller.availablePresets())
		{
			if (selected.presetKey.equals(preset.key))
			{
				return selected.presetVersion < preset.version;
			}
		}
		return false;
	}

	private ResultFilter selectedFilter()
	{
		ResultFilter selected = (ResultFilter) resultFilter.getSelectedItem();
		return selected == null ? ResultFilter.ALL : selected;
	}

	private String statusLabel(RequirementStatus status)
	{
		return status == RequirementStatus.SATISFIED ? "READY"
			: status == RequirementStatus.IGNORED ? "IGNORED"
			: status == RequirementStatus.OPTIONAL_MISSING ? "OPTIONAL"
			: status == RequirementStatus.UNKNOWN_CHARGES ? "CHECK CHARGES"
			: status == RequirementStatus.MANUAL_CHECK ? "MANUAL CHECK"
			: status == RequirementStatus.UNSUPPORTED ? "MANUAL CHECK" : "MISSING";
	}

	private Color statusAccent(RequirementStatus status)
	{
		return status == RequirementStatus.SATISFIED ? PackCheckTheme.READY
			: status == RequirementStatus.IGNORED ? PackCheckTheme.MUTED
			: status == RequirementStatus.OPTIONAL_MISSING || status == RequirementStatus.UNKNOWN_CHARGES
			|| status == RequirementStatus.MANUAL_CHECK
			|| status == RequirementStatus.UNSUPPORTED ? PackCheckTheme.WARNING : PackCheckTheme.MISSING;
	}

	private String html(String body)
	{
		return "<html><body style='font-family:sans-serif;font-size:11px;color:#c6c6c6;background:#1e1e1e'>"
			+ body + "</body></html>";
	}

	private String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;")
			.replace(">", "&gt;").replace("\"", "&quot;");
	}

	private Pack selectedPack()
	{
		if (store.composition.mainPackId == null)
		{
			return null;
		}
		return store.packs.stream().filter(pack -> store.composition.mainPackId.equals(pack.id)).findFirst().orElse(null);
	}

	private Pack selectedEquipmentPack()
	{
		if (store.composition.equipmentPackId == null)
		{
			return null;
		}
		return store.packs.stream().filter(pack -> store.composition.equipmentPackId.equals(pack.id))
			.findFirst().orElse(null);
	}

	private String baseName(Pack selected)
	{
		if (selected == null || selected.basePackId == null)
		{
			return "none";
		}
		return store.packs.stream().filter(pack -> selected.basePackId.equals(pack.id))
			.map(pack -> pack.name).findFirst().orElse("missing pack");
	}

	private String activeAddOnNames()
	{
		List<String> names = store.packs.stream().filter(pack -> store.composition.addOnPackIds.contains(pack.id))
			.map(pack -> pack.name).collect(Collectors.toList());
		return names.isEmpty() ? "none" : String.join(", ", names);
	}

	private String compactName(String name)
	{
		if (name != null && name.startsWith("["))
		{
			int categoryEnd = name.indexOf("] ");
			if (categoryEnd >= 0)
			{
				return name.substring(categoryEnd + 2);
			}
		}
		return name == null ? "Untitled pack" : name;
	}

	private enum ResultFilter
	{
		ALL("Trip - everything"),
		PACK("Pack - inventory"),
		WEAR("Wear - equipped"),
		MANUAL("Manual checks"),
		NEEDS_ATTENTION("Needs attention"),
		READY("Ready only");

		private final String label;

		ResultFilter(String label)
		{
			this.label = label;
		}

		private boolean includes(RequirementResult result)
		{
			RequirementStatus status = result.status;
			if (this == ALL)
			{
				return true;
			}
			if (this == PACK)
			{
				return result.resolvedRequirement.requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
					&& result.resolvedRequirement.requirement.location
					!= com.packcheck.model.LocationScope.EQUIPMENT_ONLY;
			}
			if (this == WEAR)
			{
				return result.resolvedRequirement.requirement.measurement != MeasurementType.MANUAL_CONFIRMATION
					&& result.resolvedRequirement.requirement.location
					== com.packcheck.model.LocationScope.EQUIPMENT_ONLY;
			}
			if (this == MANUAL)
			{
				return result.resolvedRequirement.requirement.measurement == MeasurementType.MANUAL_CONFIRMATION;
			}
			boolean ready = status == RequirementStatus.SATISFIED || status == RequirementStatus.IGNORED;
			return this == READY ? ready : !ready;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private static final class PackRenderer extends JPanel implements ListCellRenderer<Pack>
	{
		private final JLabel name = new JLabel();
		private final JLabel detail = new JLabel();

		private PackRenderer()
		{
			super(new BorderLayout(0, 2));
			setOpaque(true);
			name.setForeground(PackCheckTheme.TEXT);
			name.setFont(name.getFont().deriveFont(Font.BOLD, 14f));
			detail.setForeground(PackCheckTheme.MUTED);
			detail.setFont(detail.getFont().deriveFont(11f));
			add(name, BorderLayout.CENTER);
			add(detail, BorderLayout.SOUTH);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends Pack> list, Pack pack, int index, boolean selected,
			boolean focused)
		{
			name.setText(compactListText(pack.name));
			if (pack.presetKey != null)
			{
				detail.setText("PRESET  |  " + pack.recommendedInventorySlots + " pack  |  "
					+ pack.switchInventorySlots + " switch  |  " + pack.lootInventorySlots + " flex");
			}
			else if (pack.type == PackType.EQUIPMENT)
			{
				detail.setText("WEAR KIT  |  equipped-slot validation");
			}
			else if (pack.type == PackType.TRIP)
			{
				detail.setText("COMPLETE TRIP  |  inventory + equipment");
			}
			else
			{
				detail.setText(pack.addOnEligible ? "REUSABLE ADD-ON" : "CUSTOM PACK");
			}
			setBackground(selected ? PackCheckTheme.SURFACE_RAISED : PackCheckTheme.BACKGROUND);
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, selected ? 3 : 0, 0, 0, PackCheckTheme.ACCENT),
				BorderFactory.createCompoundBorder(
					BorderFactory.createMatteBorder(0, 0, 1, 0, PackCheckTheme.BORDER),
					BorderFactory.createEmptyBorder(5, 7, 5, 7))));
			setToolTipText(pack.presetMethod == null || pack.presetMethod.isEmpty() ? pack.name : pack.presetMethod);
			return this;
		}

		private static String compactListText(String text)
		{
			if (text == null)
			{
				return "";
			}
			if (text.startsWith("[") && text.contains("] "))
			{
				text = text.substring(text.indexOf("] ") + 2);
			}
			text = text.replace('\u2013', '-').replace('\u2014', '-');
			return compactRaidName(text);
		}

		private static String compactRaidName(String text)
		{
			return text.startsWith("Tombs of Amascut - ") ? "ToA - " + text.substring(19)
				: text.startsWith("Theatre of Blood - ") ? "ToB - " + text.substring(19)
				: text.startsWith("Chambers of Xeric - ") ? "CoX - " + text.substring(20) : text;
		}
	}
}

