import net.runelite.client.ui.ColorScheme;

final class PackCheckTheme
{
	/** RuneLite-native palette with the same orange players already read as an active control. */
	static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
	static final Color SURFACE = ColorScheme.DARKER_GRAY_COLOR;
	static final Color SURFACE_RAISED = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	static final Color BORDER = ColorScheme.BORDER_COLOR;
	static final Color TEXT = ColorScheme.TEXT_COLOR;
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color ACCENT = ColorScheme.BRAND_ORANGE;
	static final Color ACCENT_HOVER = new Color(240, 153, 12);
	static final Color READY = ColorScheme.PROGRESS_COMPLETE_COLOR;
	static final Color MISSING = ColorScheme.PROGRESS_ERROR_COLOR;
	static final Color WARNING = ColorScheme.PROGRESS_INPROGRESS_COLOR;
	static final Color ACCENT_DARK = new Color(66, 48, 19);
	static final Color READY_DARK = new Color(27, 58, 30);
	static final Color MISSING_DARK = new Color(64, 29, 29);
	static final Color WARNING_DARK = new Color(67, 49, 20);

	private PackCheckTheme()
	{
	}

	static void primary(JButton button)
	{
		button(button, ACCENT, ACCENT_HOVER, DARKER_TEXT);
	}

	static void secondary(JButton button)
	{
		button(button, SURFACE_RAISED, ColorScheme.MEDIUM_GRAY_COLOR, TEXT);
	}

	private static final Color DARKER_TEXT = new Color(24, 20, 14);

	private static void button(JButton button, Color normal, Color hover, Color foreground)
	{
		button.setUI(new BasicButtonUI());
		button.setOpaque(true);
		button.setBackground(normal);
		button.setForeground(foreground);
		button.setFocusPainted(false);
		button.setFont(button.getFont().deriveFont(Font.BOLD, 13f));
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BORDER),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				if (button.isEnabled())
				{
					button.setBackground(hover);
				}
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				button.setBackground(normal);
			}
		});
	}

	static final class Surface extends JPanel
	{
		private final int radius;

		Surface(int radius)
		{
			this.radius = radius;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int nativeRadius = Math.min(6, radius);
			g.setColor(SURFACE);
			g.fillRoundRect(0, 0, getWidth(), getHeight(), nativeRadius, nativeRadius);
			g.setColor(BORDER);
			g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, nativeRadius, nativeRadius);
			g.dispose();
			super.paintComponent(graphics);
		}
	}

	static final class BrandMark extends JComponent
	{
		private final int size;

		BrandMark(int size)
		{
			this.size = size;
			setPreferredSize(new Dimension(size, size));
			setMinimumSize(new Dimension(size, size));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(SURFACE_RAISED);
			g.fillRoundRect(0, 0, size, size, 5, 5);
			g.setColor(ACCENT);
			g.drawRoundRect(0, 0, size - 1, size - 1, 5, 5);

			int unit = Math.max(4, size / 7);
			int gap = Math.max(3, size / 10);
			int start = size / 5;
			g.setColor(new Color(220, 138, 0, 155));
			for (int row = 0; row < 2; row++)
			{
				for (int column = 0; column < 2; column++)
				{
					g.drawRoundRect(start + column * (unit + gap), start + row * (unit + gap), unit, unit, 3, 3);
				}
			}

			g.setColor(new Color(255, 225, 165));
			g.setStroke(new BasicStroke(Math.max(2f, size / 13f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(size / 2 - 3, size * 2 / 3, size / 2 + 1, size * 2 / 3 + 4);
			g.drawLine(size / 2 + 1, size * 2 / 3 + 4, size * 4 / 5, size * 2 / 5);
			g.dispose();
		}
	}
}

