		JComboBox<PackChoice> base = new JComboBox<>();
		base.addItem(new PackChoice(null, "None"));
		for (Pack pack : allPacks)
		{
			if (!pack.id.equals(copy.id))
			{
				PackChoice choice = new PackChoice(pack.id, pack.name);
				base.addItem(choice);
				if (pack.id.equals(copy.basePackId))
				{
					base.setSelectedItem(choice);
				}
			}
		}
		JCheckBox addOn = new JCheckBox("Reusable add-on pack", copy.addOnEligible);
		JComboBox<ExtraItemMode> extras = new JComboBox<>(ExtraItemMode.values());
		extras.setSelectedItem(copy.extraItemMode);
		JTextField method = new JTextField(copy.presetMethod == null ? "" : copy.presetMethod, 24);
		JSpinner plannedSlots = new JSpinner(new SpinnerNumberModel(copy.recommendedInventorySlots, 0, 28, 1));
		JSpinner switchSlots = new JSpinner(new SpinnerNumberModel(copy.switchInventorySlots, 0, 28, 1));
		JSpinner lootSlots = new JSpinner(new SpinnerNumberModel(copy.lootInventorySlots, 0, 28, 1));

		DefaultListModel<PackRequirement> requirements = new DefaultListModel<>();
		copy.requirements.forEach(requirements::addElement);
		JList<PackRequirement> requirementList = new JList<>(requirements);
		requirementList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		requirementList.setCellRenderer(new RequirementRenderer());

		JButton add = new JButton("Add");
		add.addActionListener(event ->
		{
			PackRequirement created = RequirementEditorDialog.edit(parent, new PackRequirement());
			if (created != null)
			{
				requirements.addElement(created);
			}
		});
		JButton edit = new JButton("Edit");
		edit.addActionListener(event ->
		{
			int index = requirementList.getSelectedIndex();
			if (index >= 0)
			{
				PackRequirement edited = RequirementEditorDialog.edit(parent, requirements.get(index));
				if (edited != null)
				{
					requirements.set(index, edited);
				}
			}
		});
		JButton remove = new JButton("Remove");
		remove.addActionListener(event ->
		{
			int index = requirementList.getSelectedIndex();
			if (index >= 0)
			{
				requirements.remove(index);
			}
		});
		JButton override = new JButton("Override inherited");
		override.addActionListener(event -> addInheritedOverride(parent, copy, allPacks,
			((PackChoice) base.getSelectedItem()).id, requirements));

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		buttons.add(add);
		buttons.add(edit);
		buttons.add(remove);
		buttons.add(override);
		JPanel requirementsPanel = new JPanel(new BorderLayout(4, 4));
		requirementsPanel.setBorder(BorderFactory.createTitledBorder("Local requirements and overrides"));
		requirementsPanel.add(new JScrollPane(requirementList), BorderLayout.CENTER);
		requirementsPanel.add(buttons, BorderLayout.SOUTH);

		JTextArea contexts = new JTextArea(formatContexts(copy.contextRules), 6, 30);
		contexts.setToolTipText("Optional suggestion metadata only; no gameplay action is performed");
		JPanel contextsPanel = new JPanel(new BorderLayout(4, 4));
		contextsPanel.setBorder(BorderFactory.createTitledBorder("Optional context rules (suggestion metadata)"));
		contextsPanel.add(new JLabel("One per line: region:value, bank:value, slayer:value, location:value"), BorderLayout.NORTH);
		contextsPanel.add(new JScrollPane(contexts), BorderLayout.CENTER);
		JTextArea planNotes = new JTextArea(copy.presetPlanNotes == null ? "" : copy.presetPlanNotes, 4, 30);
		planNotes.setLineWrap(true);
		planNotes.setWrapStyleWord(true);
		JPanel planningPanel = new JPanel(new BorderLayout(4, 4));
		planningPanel.setBorder(BorderFactory.createTitledBorder("Packing-plan explanation"));
		planningPanel.add(new JScrollPane(planNotes), BorderLayout.CENTER);
		JPanel detailPanels = new JPanel(new GridLayout(2, 1, 4, 4));
		detailPanels.add(planningPanel);
		detailPanels.add(contextsPanel);

		JPanel metadata = new JPanel(new GridLayout(0, 2, 6, 6));
		metadata.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		metadata.add(new JLabel("Pack name"));
		metadata.add(name);
		metadata.add(new JLabel("Checklist type"));
		metadata.add(type);
		metadata.add(new JLabel("Base pack"));
		metadata.add(base);
		metadata.add(new JLabel("Composition"));
		metadata.add(addOn);
		metadata.add(new JLabel("Unexpected items"));
		metadata.add(extras);
		metadata.add(new JLabel("Method / variant"));
		metadata.add(method);
		metadata.add(new JLabel("Checked / switch / loot slots"));
		JPanel slotCounts = new JPanel(new GridLayout(1, 3, 4, 0));
		slotCounts.add(plannedSlots);
		slotCounts.add(switchSlots);
		slotCounts.add(lootSlots);
		metadata.add(slotCounts);

		JSplitPane split = new JSplitPane(JSplitPane.VERTICAL_SPLIT, requirementsPanel, detailPanels);
		split.setResizeWeight(0.72);
		JPanel content = new JPanel(new BorderLayout(6, 6));
		content.add(metadata, BorderLayout.NORTH);
		content.add(split, BorderLayout.CENTER);
		content.setPreferredSize(new Dimension(680, 650));

		while (true)
		{
			int result = JOptionPane.showConfirmDialog(parent, content, "Edit pack",
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
			if (result != JOptionPane.OK_OPTION)
			{
				return null;
			}
			try
			{
				String packName = name.getText().trim();
				if (packName.isEmpty())
				{
					throw new IllegalArgumentException("Pack name is required");
				}
				copy.name = packName;
				copy.type = (PackType) type.getSelectedItem();
				copy.basePackId = ((PackChoice) base.getSelectedItem()).id;
				copy.addOnEligible = addOn.isSelected();
				copy.extraItemMode = (ExtraItemMode) extras.getSelectedItem();
				copy.presetMethod = method.getText().trim();
				copy.recommendedInventorySlots = (Integer) plannedSlots.getValue();
				copy.switchInventorySlots = (Integer) switchSlots.getValue();
				copy.lootInventorySlots = (Integer) lootSlots.getValue();
				copy.flexibleInventorySlots = copy.switchInventorySlots + copy.lootInventorySlots;
				copy.presetPlanNotes = planNotes.getText().trim();
				if (copy.type != PackType.EQUIPMENT
					&& (copy.recommendedInventorySlots > 0 || copy.flexibleInventorySlots > 0)
					&& copy.recommendedInventorySlots + copy.flexibleInventorySlots != 28)
				{
					throw new IllegalArgumentException("Checked, switch, and loot inventory slots must total 28");
				}
				if (copy.type == PackType.EQUIPMENT && (copy.recommendedInventorySlots > 0
					|| copy.switchInventorySlots > 0 || copy.lootInventorySlots > 0))
				{
					throw new IllegalArgumentException("Equipment kits cannot allocate inventory slots");
				}
				if (copy.type == PackType.EQUIPMENT && copy.addOnEligible)
				{
					throw new IllegalArgumentException("Wear kits cannot be reusable Trip add-ons");
				}
				copy.requirements = new ArrayList<>();
				for (int index = 0; index < requirements.size(); index++)
				{
					copy.requirements.add(requirements.get(index));
				}
				copy.contextRules = parseContexts(contexts.getText());
				if (copy.extraItemMode == ExtraItemMode.ENFORCE_EXACT)
				{
					int confirm = JOptionPane.showConfirmDialog(parent,
						"Exact-inventory enforcement can be noisy. Keep this mode?", "Exact inventory warning",
						JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
					if (confirm != JOptionPane.YES_OPTION)
					{
						continue;
					}
				}
				return copy;
			}
			catch (IllegalArgumentException exception)
			{
				JOptionPane.showMessageDialog(parent, exception.getMessage(), "Invalid pack", JOptionPane.ERROR_MESSAGE);
			}
		}
	}

	private static void addInheritedOverride(Component parent, Pack editingPack, Collection<Pack> allPacks,
		String basePackId, DefaultListModel<PackRequirement> localRequirements)
	{
		if (basePackId == null)
		{
			JOptionPane.showMessageDialog(parent, "Select a base pack first.");
			return;
		}
		try
		{
			List<ResolvedRequirement> inherited = new PackResolver().resolveSingle(basePackId, allPacks);
			List<RequirementChoice> choices = new ArrayList<>();
			for (ResolvedRequirement resolved : inherited)
			{
				boolean alreadyLocal = false;
				for (int index = 0; index < localRequirements.size(); index++)
				{
					alreadyLocal |= localRequirements.get(index).id.equals(resolved.requirement.id);
				}
				if (!alreadyLocal)
				{
					choices.add(new RequirementChoice(resolved));
				}
			}
			if (choices.isEmpty())
			{
				JOptionPane.showMessageDialog(parent, "Every inherited requirement already has a local override.");
				return;
			}
			RequirementChoice chosen = (RequirementChoice) JOptionPane.showInputDialog(parent,
				"Choose an inherited requirement. Disable it in the editor to ignore it only in this child.",
				"Override inherited requirement", JOptionPane.PLAIN_MESSAGE, null, choices.toArray(), choices.get(0));
			if (chosen != null)
			{
				PackRequirement edited = RequirementEditorDialog.edit(parent, chosen.resolved.requirement);
				if (edited != null)
				{
					localRequirements.addElement(edited);
				}
			}
		}
		catch (IllegalArgumentException exception)
		{
			JOptionPane.showMessageDialog(parent, exception.getMessage(), "Cannot resolve base pack",
				JOptionPane.ERROR_MESSAGE);
		}
	}

	private static String formatContexts(List<PackContextRule> rules)
	{
		StringBuilder text = new StringBuilder();
		for (PackContextRule rule : rules)
		{
			if (text.length() > 0)
			{
				text.append('\n');
			}
			text.append(rule.type.name().toLowerCase()).append(':').append(rule.value);
		}
		return text.toString();
	}

	private static ArrayList<PackContextRule> parseContexts(String text)
	{
		ArrayList<PackContextRule> rules = new ArrayList<>();
		for (String rawLine : text.split("\\R"))
		{
			String line = rawLine.trim();
			if (line.isEmpty())
			{
				continue;
			}
			int separator = line.indexOf(':');
			if (separator < 1 || separator == line.length() - 1)
			{
				throw new IllegalArgumentException("Invalid context rule: " + line);
			}
			String type = line.substring(0, separator).trim().toUpperCase();
			if ("BANK".equals(type))
			{
				type = "BANK_LOCATION";
			}
			else if ("SLAYER".equals(type))
			{
				type = "SLAYER_TASK";
			}
			else if ("LOCATION".equals(type))
			{
				type = "USER_LOCATION";
			}
			PackContextRule rule = new PackContextRule();
			rule.id = UUID.randomUUID().toString();
			try
			{
				rule.type = PackContextRule.Type.valueOf(type);
			}
			catch (IllegalArgumentException exception)
			{
				throw new IllegalArgumentException("Unknown context type: " + line, exception);
			}
			rule.value = line.substring(separator + 1).trim();
			rule.enabled = true;
			rules.add(rule);
		}
		return rules;
	}

	private static final class PackChoice
	{
		private final String id;
		private final String name;

		private PackChoice(String id, String name)
		{
			this.id = id;
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}

		@Override
		public boolean equals(Object other)
		{
			return other instanceof PackChoice && java.util.Objects.equals(id, ((PackChoice) other).id);
		}

		@Override
		public int hashCode()
		{
			return java.util.Objects.hashCode(id);
		}
	}

	private static final class RequirementChoice
	{
		private final ResolvedRequirement resolved;

		private RequirementChoice(ResolvedRequirement resolved)
		{
			this.resolved = resolved;
		}

		@Override
		public String toString()
		{
			return resolved.requirement.displayName + " — from " + resolved.sourcePackName;
		}
	}

	private static final class RequirementRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected,
			boolean focused)
		{
			PackRequirement requirement = (PackRequirement) value;
			String marker = !requirement.enabled ? "[SKIP] Ignored" : requirement.required ? "[R] Required" : "[O] Optional";
			return super.getListCellRendererComponent(list, marker + " — " + requirement.displayName,
				index, selected, focused);
		}
	}
}

