			String category = (String) categories.getSelectedItem();
			String query = search.getText().trim().toLowerCase(Locale.ENGLISH);
			model.clear();
			for (PresetSummary preset : presets)
			{
				boolean categoryMatches = "All activities".equals(category) || preset.category.equals(category);
				boolean queryMatches = query.isEmpty() || preset.name.toLowerCase(Locale.ENGLISH).contains(query)
					|| preset.method.toLowerCase(Locale.ENGLISH).contains(query)
					|| preset.category.toLowerCase(Locale.ENGLISH).contains(query);
