	static String format(PresetSummary preset)
	{
		if (preset == null)
		{
			return html("<p>Select a preset to review its complete plan.</p>");
		}
		StringBuilder rows = new StringBuilder();
		for (String line : preset.checklist)
		{
			String[] parts = line.split(" \\| ", 3);
			String kind = parts.length > 0 ? parts[0] : "Required";
			String name = parts.length > 1 ? parts[1] : line;
			String target = parts.length > 2 ? parts[2] : "";
			String color = "Optional".equals(kind) || "Manual".equals(kind) ? "#e5a838" : "#c6c6c6";
			rows.append("<tr><td valign='top'><font color='").append(color).append("'><b>")
				.append(escape(kind)).append("</b></font></td><td><b>").append(escape(name))
				.append("</b><br><font color='#a5a5a5'>").append(escape(target)).append("</font></td></tr>");
		}
		return html("<p><font color='#dc8a00'><b>" + escape(preset.category.toUpperCase())
			+ "  /  READY-MADE PLAN</b></font></p><h2>" + escape(preset.name) + "</h2>"
			+ "<p><font color='#a5a5a5'><b>METHOD</b></font><br><b>" + escape(preset.method) + "</b></p>"
			+ "<table width='100%' bgcolor='#262626' cellpadding='9'><tr><td><b>"
			+ preset.plannedSlots + " checked slots</b><br>" + preset.switchSlots
			+ " switch reserve | " + preset.lootSlots + " loot/flex</td><td align='right'>"
			+ "<font color='#dc8a00'><b>28 / 28 ACCOUNTED</b></font>"
			+ "<br>Preset v" + preset.version + " | "
			+ escape(preset.reviewedOn) + "</td></tr></table>"
			+ "<p>" + escape(preset.description) + "</p>"
			+ "<p><font color='#a5a5a5'><b>WHY THIS PLAN</b></font><br>" + escape(preset.planNotes) + "</p>"
			+ "<h3>What to pack</h3><table width='100%' cellspacing='0' cellpadding='6'>" + rows + "</table>"
			+ "<hr><p><b>Research source</b><br>" + escape(preset.sourceUrl) + "</p>"
			+ "<p><font color='#e5a838'>This preset checks carried inventory only. Add a separate Wear kit for "
			+ "equipped gear. Rune-pouch contents and other unobservable details stay explicit manual checks.</font></p>");
	}

	private static String html(String body)
	{
		return "<html><body style='font-family:sans-serif;font-size:11px;color:#c6c6c6;background:#282828'>"
			+ body + "</body></html>";
	}

	private static final class PresetRenderer extends JPanel implements ListCellRenderer<PresetSummary>
	{
