		}

		@Override
		public Component getListCellRendererComponent(JList<? extends PresetSummary> list, PresetSummary preset,
			int index, boolean selected, boolean focused)
		{
			name.setText(compactListText(preset.name));
			detail.setText(preset.category.toUpperCase() + "  |  " + preset.plannedSlots + " pack  |  "
				+ preset.switchSlots + " switch  |  " + preset.lootSlots + " flex");
