package com.packcheck.service;

import com.packcheck.model.Pack;
import com.packcheck.model.PresetSummary;
import com.packcheck.model.MatchOption;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.LocationScope;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class BuiltInPresetServiceTest
{
	private BuiltInPresetService presets;

	@Before
	public void setUp()
	{
		presets = new BuiltInPresetService();
	}

	@Test
	public void exposesCuratedCatalogWithUniqueKeysAndSources()
	{
		List<PresetSummary> summaries = presets.summaries();
		assertEquals(103, summaries.size());
		Set<String> keys = new HashSet<>();
		for (PresetSummary summary : summaries)
		{
			assertTrue(keys.add(summary.key));
			assertTrue(summary.sourceUrl.startsWith("https://oldschool.runescape.wiki/"));
			assertFalse(summary.description.isEmpty());
			assertFalse(summary.method.isEmpty());
			assertFalse(summary.planNotes.isEmpty());
			assertEquals(28, summary.plannedSlots + summary.flexibleSlots);
			assertEquals(3, summary.version);
			assertFalse(summary.checklist.isEmpty());
		}
	}

	@Test
	public void createsEditableCopyAndResetPreservesInstalledIdentity()
	{
		Pack installed = presets.create("boss.vorkath_ranged");
		String installedId = installed.id;
		int defaultRequirementCount = installed.requirements.size();
		installed.name = "My short Vorkath trip";
		installed.requirements.remove(0);

		Pack reset = presets.reset(installed);
		assertEquals(installedId, reset.id);
		assertEquals("boss.vorkath_ranged", reset.presetKey);
		assertEquals(3, reset.presetVersion);
		assertEquals(defaultRequirementCount, reset.requirements.size());
		assertEquals("[Boss] Vorkath — ranged", reset.name);
	}

	@Test
	public void researchedCatalogShipsBossRaidAndSlayerInventoryOnly()
	{
		long bosses = presets.summaries().stream().filter(summary -> summary.key.startsWith("research.boss.")).count();
		long raids = presets.summaries().stream().filter(summary -> summary.key.startsWith("research.raid.")).count();
		long slayer = presets.summaries().stream().filter(summary -> summary.key.startsWith("research.slayer.")).count();
		assertEquals(55, bosses);
		assertEquals(22, raids);
		assertEquals(14, slayer);
		for (PresetSummary summary : presets.summaries())
		{
			Pack pack = presets.create(summary.key);
			assertEquals(28, pack.recommendedInventorySlots + pack.switchInventorySlots + pack.lootInventorySlots);
			for (PackRequirement requirement : pack.requirements)
			{
				assertEquals(summary.key + " contains a non-inventory default", LocationScope.INVENTORY_ONLY,
					requirement.location);
			}
		}
	}

	@Test
	public void researchedRowsBecomePreciseDoseFoodAndManualRules()
	{
		Pack obor = presets.create("research.boss.obor.first_key_melee");
		assertEquals(8, familyRequirement(obor, "prayer_potion").minimum);
		assertEquals(4, familyRequirement(obor, "energy").minimum);
		assertEquals(23, obor.requirements.stream().filter(requirement -> "High-heal food".equals(requirement.displayName))
			.findFirst().orElseThrow(() -> new AssertionError("Obor food missing")).minimum);
		PackRequirement manual = obor.requirements.stream()
			.filter(requirement -> requirement.measurement == MeasurementType.MANUAL_CONFIRMATION)
			.findFirst().orElseThrow(() -> new AssertionError("Obor manual inventory rule missing"));
		assertEquals(1, manual.recommendedSlots);

		Pack toa = presets.create("research.raid.tombs_of_amascut.entry_learner");
		assertEquals(16, toa.recommendedInventorySlots);
		assertEquals(11, toa.switchInventorySlots);
		assertEquals(1, toa.lootInventorySlots);
		assertEquals(24, familyRequirement(toa, "saradomin_brew").minimum);
		assertEquals(16, familyRequirement(toa, "super_restore").minimum);
		assertEquals(8, familyRequirement(toa, "super_combat").minimum);
	}

	@Test
	public void precisePlansExposeBottleCountsConstraintsAndStackTargets()
	{
		Pack fightCaves = presets.create("minigame.fight_caves_ranged");
		assertEquals(28, fightCaves.recommendedInventorySlots);
		assertEquals(0, fightCaves.flexibleInventorySlots);
		assertEquals(24, requirement(fightCaves, "brews").minimum);
		assertEquals(6, requirement(fightCaves, "brews").recommendedSlots);
		assertEquals(80, requirement(fightCaves, "restores").minimum);
		assertEquals(20, requirement(fightCaves, "restores").recommendedSlots);
		assertEquals(8, requirement(fightCaves, "brew_restore_floor").minimum);
		assertEquals(0, requirement(fightCaves, "brew_restore_floor").recommendedSlots);

		Pack vorkath = presets.create("boss.vorkath_ranged");
		assertEquals(100, requirement(vorkath, "ammo_switch").minimum);
		assertEquals(1, requirement(vorkath, "ammo_switch").recommendedSlots);
		assertEquals(16, requirement(vorkath, "prayer").minimum);

		Pack vanstrom = presets.create("quest.sotf_vanstrom");
		assertEquals(20, requirement(vanstrom, "bloodveld").minimum);
		assertEquals(26, vanstrom.recommendedInventorySlots);
		assertEquals(2, vanstrom.flexibleInventorySlots);
	}

	@Test
	public void everyPresetRuleExplainsItsPackingTarget()
	{
		for (PresetSummary summary : presets.summaries())
		{
			Pack pack = presets.create(summary.key);
			assertEquals(28, pack.recommendedInventorySlots + pack.flexibleInventorySlots);
			assertFalse(pack.presetMethod.isEmpty());
			assertFalse(pack.presetPlanNotes.isEmpty());
			int requiredPlannedSlots = 0;
			for (PackRequirement requirement : pack.requirements)
			{
				assertNotNull(requirement.recommendation);
				assertFalse(summary.key + " has an unexplained target for " + requirement.id,
					requirement.recommendation.isEmpty());
				if (requirement.required)
				{
					requiredPlannedSlots += requirement.recommendedSlots;
				}
			}
			assertEquals(summary.key + " has inconsistent required-slot accounting",
				pack.recommendedInventorySlots, requiredPlannedSlots);
		}
	}

	@Test
	public void duplicateBecomesIndependentCustomPack()
	{
		Pack installed = presets.create("minigame.fight_caves_ranged");
		Pack duplicate = installed.copyWithNewIds();
		assertNull(duplicate.presetKey);
		assertEquals(0, duplicate.presetVersion);
		assertFalse(installed.id.equals(duplicate.id));
	}

	@Test
	public void everyPresetDoseAndChargeFamilyIsSupported()
	{
		DoseService doses = new DoseService();
		ChargeService charges = new ChargeService();
		for (PresetSummary summary : presets.summaries())
		{
			for (PackRequirement requirement : presets.create(summary.key).requirements)
			{
				for (MatchOption option : requirement.alternatives)
				{
					if (option.familyKey == null)
					{
						continue;
					}
					if (requirement.measurement == MeasurementType.TOTAL_DOSES)
					{
						assertTrue(summary.key + " uses unsupported dose family " + option.familyKey,
							doses.supports(option.familyKey));
					}
					else if (requirement.measurement == MeasurementType.KNOWN_CHARGES)
					{
						assertTrue(summary.key + " uses unsupported charge family " + option.familyKey,
							charges.supports(option.familyKey));
					}
				}
			}
		}
	}

	private PackRequirement requirement(Pack pack, String ruleKey)
	{
		String id = pack.presetKey + ":" + ruleKey;
		return pack.requirements.stream().filter(requirement -> id.equals(requirement.id))
			.findFirst().orElseThrow(() -> new AssertionError("Missing preset requirement " + id));
	}

	private PackRequirement familyRequirement(Pack pack, String familyKey)
	{
		return pack.requirements.stream().filter(requirement -> requirement.alternatives.stream()
			.anyMatch(option -> familyKey.equals(option.familyKey))).findFirst()
			.orElseThrow(() -> new AssertionError("Missing family " + familyKey + " in " + pack.presetKey));
	}
}

package com.packcheck.service;

import com.packcheck.model.ItemStackSnapshot;
import com.packcheck.model.LocationScope;
