import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class CaptureServiceTest
{
	@Test
	public void captureProducesReviewableLocationQuantityDoseAndChargeRules()
	{
		CaptureService service = new CaptureService(new DoseService(), new ChargeService());
		PackSnapshot snapshot = new PackSnapshot(Arrays.asList(
			new ItemStackSnapshot(1000, 50, 0, "Bolts"),
			new ItemStackSnapshot(ItemID._3DOSEPRAYERRESTORE, 1, 1, "Prayer potion(3)"),
			new ItemStackSnapshot(ItemID._1DOSEPRAYERRESTORE, 1, 2, "Prayer potion(1)"),
			new ItemStackSnapshot(ItemID.RING_OF_DUELING_5, 1, 3, "Ring of dueling(5)")),
			Collections.singletonList(new ItemStackSnapshot(6570, 1, 1, "Fire cape")));

		Pack captured = service.capture("Jad", snapshot);
		assertEquals("Jad", captured.name);
		PackRequirement bolts = find(captured, "Bolts");
		assertEquals(LocationScope.INVENTORY_ONLY, bolts.location);
		assertEquals(50, bolts.minimum);
		PackRequirement prayer = find(captured, "Prayer potion");
		assertEquals(MeasurementType.TOTAL_DOSES, prayer.measurement);
		assertEquals(4, prayer.minimum);
		PackRequirement ring = find(captured, "Ring of dueling");
		assertEquals(MeasurementType.KNOWN_CHARGES, ring.measurement);
		assertEquals(5, ring.minimum);
		PackRequirement cape = find(captured, "Fire cape");
		assertEquals(LocationScope.EQUIPMENT_ONLY, cape.location);
		assertEquals(Integer.valueOf(1), cape.requiredEquipmentSlot);
	}

	@Test
	public void captureModesKeepPackWearAndTripResponsibilitiesSeparate()
	{
		CaptureService service = new CaptureService(new DoseService(), new ChargeService());
		PackSnapshot snapshot = new PackSnapshot(
			Collections.singletonList(new ItemStackSnapshot(1000, 1, 0, "Teleport")),
			Collections.singletonList(new ItemStackSnapshot(2000, 1, 3, "Body armour")));

		Pack inventory = service.capture("Pack", snapshot, PackType.INVENTORY);
		assertEquals(PackType.INVENTORY, inventory.type);
		assertEquals(1, inventory.requirements.size());
		assertEquals(LocationScope.INVENTORY_ONLY, inventory.requirements.get(0).location);

		Pack equipment = service.capture("Wear", snapshot, PackType.EQUIPMENT);
		assertEquals(PackType.EQUIPMENT, equipment.type);
		assertEquals(1, equipment.requirements.size());
		assertEquals(LocationScope.EQUIPMENT_ONLY, equipment.requirements.get(0).location);
		assertEquals(Integer.valueOf(3), equipment.requirements.get(0).requiredEquipmentSlot);

		Pack trip = service.capture("Trip", snapshot, PackType.TRIP);
		assertEquals(PackType.TRIP, trip.type);
		assertEquals(2, trip.requirements.size());
	}

	private PackRequirement find(Pack pack, String name)
	{
		PackRequirement requirement = pack.requirements.stream().filter(value -> name.equals(value.displayName))
			.findFirst().orElse(null);
		assertNotNull(requirement);
		return requirement;
	}
}

