		assertTrue(doses.supports("toa_smelling_salts"));
		assertTrue(doses.supports("moonlight_moth_mix"));
	}

	@Test
	public void countsStandardRaidAndTwoDoseFamilies()
	{
		assertEquals(Integer.valueOf(4), doses.doses("extended_super_antifire", ItemID._4DOSE4ANTIDRAGON));
		assertEquals(Integer.valueOf(3), doses.doses("cox_overload_strong", ItemID.RAIDS_VIAL_OVERLOAD_STRONG_3));
		assertEquals(Integer.valueOf(2), doses.doses("toa_ambrosia", ItemID.TOA_SUPPLY_PANICHEAL_2));
		assertEquals(Integer.valueOf(1), doses.doses("moonlight_moth_mix", ItemID.HUNTER_MIX_MOONMOTH_1DOSE));
	}

	@Test
	public void totalsDoseVariantsAndRejectsUnrelatedItems()
	{
		int total = doses.totalDoses("prayer_potion", Arrays.asList(
			new ItemStackSnapshot(ItemID._4DOSEPRAYERRESTORE, 2, 0, "Prayer potion(4)"),
			new ItemStackSnapshot(ItemID._1DOSEPRAYERRESTORE, 1, 1, "Prayer potion(1)"),
			new ItemStackSnapshot(ItemID.SHARK, 5, 2, "Shark")));
