package com.packcheck.service;

import com.packcheck.model.ExtraItemMode;
import com.packcheck.model.ItemStackSnapshot;
import com.packcheck.model.LocationScope;
import com.packcheck.model.MatchOption;
import com.packcheck.model.MeasurementType;
import com.packcheck.model.PackEvaluation;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackResolution;
import com.packcheck.model.PackSnapshot;
import com.packcheck.model.RequirementStatus;
import com.packcheck.model.ResolvedRequirement;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PackEvaluatorTest
{
	private DoseService doses;
	private ChargeService charges;
	private ItemFamilyService families;
	private PackEvaluator evaluator;

	@Before
	public void setUp()
	{
		doses = new DoseService();
		charges = new ChargeService();
		families = new ItemFamilyService(doses, charges);
		families.registerExplicitFamily("compatible_bolts", new HashSet<>(Arrays.asList(200, 201)));
		evaluator = new PackEvaluator(families, doses, charges);
	}

	@Test
	public void exactItemAndMinimumQuantityAreSatisfied()
	{
		PackRequirement requirement = itemRequirement("bolts", 100, 2);
		PackEvaluation evaluation = evaluate(requirement,
			new PackSnapshot(Collections.singletonList(item(100, 2, 0)), Collections.emptyList()), ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.SATISFIED, evaluation.results.get(0).status);
		assertTrue(evaluation.ready);
	}

	@Test
	public void explicitItemFamilyMatchesWithoutNames()
	{
		PackRequirement requirement = familyRequirement("compatible bolts", "compatible_bolts", 100);
		PackEvaluation evaluation = evaluate(requirement,
			new PackSnapshot(Collections.singletonList(item(201, 100, 0)), Collections.emptyList()), ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.SATISFIED, evaluation.results.get(0).status);
		assertEquals(Collections.singletonList("compatible bolts"), evaluation.results.get(0).satisfyingAlternatives);
	}

	@Test
	public void inventoryAndEquipmentScopeReportsWrongLocation()
	{
		PackRequirement requirement = itemRequirement("cape", 300, 1);
		requirement.location = LocationScope.EQUIPMENT_ONLY;
		PackEvaluation evaluation = evaluate(requirement,
			new PackSnapshot(Collections.singletonList(item(300, 1, 0)), Collections.emptyList()), ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.WRONG_LOCATION, evaluation.results.get(0).status);
	}

	@Test
	public void equipmentSlotAndInventorySlotAreEnforced()
	{
		PackRequirement equipment = itemRequirement("cape", 301, 1);
		equipment.location = LocationScope.EQUIPMENT_ONLY;
		equipment.requiredEquipmentSlot = 1;
		PackEvaluation equipmentEvaluation = evaluate(equipment,
			new PackSnapshot(Collections.emptyList(), Collections.singletonList(item(301, 1, 2))), ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.WRONG_EQUIPMENT_SLOT, equipmentEvaluation.results.get(0).status);

		PackRequirement inventory = itemRequirement("teleport", 302, 1);
		inventory.location = LocationScope.INVENTORY_ONLY;
		inventory.fixedInventorySlot = 4;
		PackEvaluation inventoryEvaluation = evaluate(inventory,
			new PackSnapshot(Collections.singletonList(item(302, 1, 3)), Collections.emptyList()), ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.WRONG_INVENTORY_SLOT, inventoryEvaluation.results.get(0).status);
	}

	@Test
	public void exactMinimumAndMaximumQuantitiesProduceVisibleFailures()
	{
		PackRequirement minimum = itemRequirement("food", 400, 5);
		assertEquals(RequirementStatus.INSUFFICIENT_QUANTITY, evaluate(minimum,
			new PackSnapshot(Collections.singletonList(item(400, 4, 0)), Collections.emptyList()), ExtraItemMode.IGNORE)
			.results.get(0).status);

		PackRequirement exact = itemRequirement("teleports", 401, 1);
		exact.exact = 2;
		assertEquals(RequirementStatus.EXTRA_ITEM, evaluate(exact,
			new PackSnapshot(Collections.singletonList(item(401, 3, 0)), Collections.emptyList()), ExtraItemMode.IGNORE)
			.results.get(0).status);

		PackRequirement maximum = itemRequirement("keys", 402, 1);
		maximum.maximum = 3;
		assertEquals(RequirementStatus.EXTRA_ITEM, evaluate(maximum,
			new PackSnapshot(Collections.singletonList(item(402, 4, 0)), Collections.emptyList()), ExtraItemMode.IGNORE)
			.results.get(0).status);
	}

	@Test
	public void potionDosesAggregateAcrossMultiplePartialPotions()
	{
		PackRequirement requirement = familyRequirement("Prayer doses", "prayer_potion", 4);
		requirement.measurement = MeasurementType.TOTAL_DOSES;
		PackSnapshot snapshot = new PackSnapshot(Arrays.asList(
			item(ItemID._3DOSEPRAYERRESTORE, 1, 0),
			item(ItemID._1DOSEPRAYERRESTORE, 1, 1)), Collections.emptyList());
		PackEvaluation evaluation = evaluate(requirement, snapshot, ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.SATISFIED, evaluation.results.get(0).status);
		assertEquals(4, evaluation.results.get(0).actual);
	}

	@Test
	public void itemAndDoseAlternativesExplainWhatSatisfiedThem()
	{
		PackRequirement itemAlternative = itemRequirement("House teleport", 500, 1);
		itemAlternative.alternatives.add(MatchOption.exact(501, "Construction cape"));
		PackEvaluation items = evaluate(itemAlternative,
			new PackSnapshot(Collections.singletonList(item(501, 1, 0)), Collections.emptyList()), ExtraItemMode.IGNORE);
		assertEquals(Collections.singletonList("Construction cape"), items.results.get(0).satisfyingAlternatives);

		PackRequirement doseAlternative = familyRequirement("Restoration doses", "prayer_potion", 8);
		doseAlternative.alternatives.add(MatchOption.family("super_restore", "Super restore"));
		doseAlternative.measurement = MeasurementType.TOTAL_DOSES;
		PackSnapshot snapshot = new PackSnapshot(Arrays.asList(
			item(ItemID._4DOSEPRAYERRESTORE, 1, 0), item(ItemID._4DOSE2RESTORE, 1, 1)), Collections.emptyList());
		PackEvaluation doseEvaluation = evaluate(doseAlternative, snapshot, ExtraItemMode.IGNORE);
		assertEquals(8, doseEvaluation.results.get(0).actual);
		assertEquals(Arrays.asList("Restoration doses", "Super restore"), doseEvaluation.results.get(0).satisfyingAlternatives);
	}

	@Test
	public void knownAndUnknownChargesAreNeverGuessed()
	{
		PackRequirement known = familyRequirement("Ring of dueling", "ring_of_dueling", 3);
		known.measurement = MeasurementType.KNOWN_CHARGES;
		PackEvaluation knownEvaluation = evaluate(known,
			new PackSnapshot(Collections.singletonList(item(ItemID.RING_OF_DUELING_3, 1, 0)), Collections.emptyList()),
			ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.SATISFIED, knownEvaluation.results.get(0).status);
		assertEquals(3, knownEvaluation.results.get(0).actual);

		PackRequirement unknown = itemRequirement("Unknown charged item", 999_999, 1);
		unknown.measurement = MeasurementType.KNOWN_CHARGES;
		PackEvaluation unknownEvaluation = evaluate(unknown,
			new PackSnapshot(Collections.singletonList(item(999_999, 1, 0)), Collections.emptyList()),
			ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.UNKNOWN_CHARGES, unknownEvaluation.results.get(0).status);
	}

	@Test
	public void optionalMissingAndExtraModesDoNotSilentlyFail()
	{
		PackRequirement optional = itemRequirement("Emergency food", 600, 1);
		optional.required = false;
		PackEvaluation optionalEvaluation = evaluate(optional, PackSnapshot.EMPTY, ExtraItemMode.IGNORE);
		assertEquals(RequirementStatus.OPTIONAL_MISSING, optionalEvaluation.results.get(0).status);
		assertTrue(optionalEvaluation.ready);

		PackRequirement required = itemRequirement("Cape", 601, 1);
		PackSnapshot withExtra = new PackSnapshot(Arrays.asList(item(601, 1, 0), item(602, 1, 1)), Collections.emptyList());
		PackEvaluation warn = evaluate(required, withExtra, ExtraItemMode.WARN);
		assertEquals(1, warn.extras.size());
		assertTrue(warn.ready);
		PackEvaluation enforce = evaluate(required, withExtra, ExtraItemMode.ENFORCE_EXACT);
		assertEquals(1, enforce.extras.size());
		assertFalse(enforce.ready);
	}

	@Test
	public void manualChecksAreExplicitAndOnlyPassAfterUserConfirmation()
	{
		PackRequirement manual = new PackRequirement();
		manual.id = "manual:runes";
		manual.displayName = "Rune pouch contents";
		manual.measurement = MeasurementType.MANUAL_CONFIRMATION;
		ResolvedRequirement resolved = new ResolvedRequirement(manual, "pack", "Test pack", false);
		PackResolution resolution = new PackResolution("Test pack", ExtraItemMode.IGNORE,
			Collections.singletonList(resolved), Collections.emptyList());

		PackEvaluation pending = evaluator.evaluate(resolution, PackSnapshot.EMPTY);
		assertEquals(RequirementStatus.MANUAL_CHECK, pending.results.get(0).status);
		assertFalse(pending.ready);
		assertEquals(1, pending.totalManualChecks());
		assertEquals(0, pending.satisfiedManualChecks());

		PackEvaluation confirmed = evaluator.evaluate(resolution, PackSnapshot.EMPTY,
			Collections.singleton(manual.id));
		assertEquals(RequirementStatus.SATISFIED, confirmed.results.get(0).status);
		assertTrue(confirmed.ready);
		assertEquals(1, confirmed.satisfiedManualChecks());
	}

	private PackEvaluation evaluate(PackRequirement requirement, PackSnapshot snapshot, ExtraItemMode extras)
	{
		ResolvedRequirement resolved = new ResolvedRequirement(requirement, "pack", "Test pack", false);
		PackResolution resolution = new PackResolution("Test pack", extras,
			Collections.singletonList(resolved), Collections.emptyList());
		return evaluator.evaluate(resolution, snapshot);
	}

	private PackRequirement itemRequirement(String name, int itemId, int minimum)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.displayName = name;
		requirement.minimum = minimum;
		requirement.alternatives.add(MatchOption.exact(itemId, name));
		return requirement;
	}

	private PackRequirement familyRequirement(String name, String family, int minimum)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.displayName = name;
		requirement.minimum = minimum;
		requirement.alternatives.add(MatchOption.family(family, name));
		return requirement;
	}

	private ItemStackSnapshot item(int id, int quantity, int slot)
	{
		return new ItemStackSnapshot(id, quantity, slot, "Item " + id);
	}
}

package com.packcheck.service;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.packcheck.model.ImportPreview;
import com.packcheck.model.MatchOption;
import com.packcheck.model.Pack;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackStore;
import com.packcheck.model.PackType;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.stream.Stream;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class PackRepositoryTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	private Gson gson;
	private Path directory;
	private PackRepository repository;

	@Before
	public void setUp() throws Exception
	{
		gson = new GsonBuilder().setPrettyPrinting().create();
		directory = temporaryFolder.newFolder("packcheck").toPath();
		repository = new PackRepository(gson, directory,
			Clock.fixed(Instant.ofEpochMilli(123456789L), ZoneOffset.UTC));
	}

	@Test
	public void persistenceRoundTripPreservesPacksCompositionAndStableIds() throws Exception
	{
		PackStore store = store("profile-a", "pack-a", "General");
		store.defaultPackId = "pack-a";
		store.composition.mainPackId = "pack-a";
		store.packs.get(0).presetKey = "boss.vorkath_ranged";
		store.packs.get(0).presetVersion = 1;
		store.packs.get(0).presetMethod = "Crossbow trip";
		store.packs.get(0).recommendedInventorySlots = 27;
		store.packs.get(0).switchInventorySlots = 1;
		store.packs.get(0).flexibleInventorySlots = 1;
		store.composition.confirmedManualRequirementIds.add("manual-a");
		store.packs.get(0).requirements.get(0).recommendation = "100+ in one stack";
		store.packs.get(0).requirements.get(0).recommendedSlots = 1;
		repository.save(store);

		PackStore loaded = repository.load("profile-a");
		assertEquals(PackStore.CURRENT_SCHEMA_VERSION, loaded.schemaVersion);
		assertEquals("profile-a", loaded.profileKey);
		assertEquals("pack-a", loaded.packs.get(0).id);
		assertEquals("requirement-a", loaded.packs.get(0).requirements.get(0).id);
		assertEquals("boss.vorkath_ranged", loaded.packs.get(0).presetKey);
		assertEquals(1, loaded.packs.get(0).presetVersion);
		assertEquals("Crossbow trip", loaded.packs.get(0).presetMethod);
		assertEquals(27, loaded.packs.get(0).recommendedInventorySlots);
		assertEquals(1, loaded.packs.get(0).switchInventorySlots);
		assertEquals(0, loaded.packs.get(0).lootInventorySlots);
		assertEquals(1, loaded.packs.get(0).flexibleInventorySlots);
		assertEquals("100+ in one stack", loaded.packs.get(0).requirements.get(0).recommendation);
		assertEquals("pack-a", loaded.composition.mainPackId);
		assertEquals("pack-a", loaded.defaultPackId);
		assertTrue(loaded.composition.confirmedManualRequirementIds.contains("manual-a"));
	}

	@Test
	public void equipmentKitSelectionRoundTripsSeparatelyFromInventoryPack() throws Exception
	{
		PackStore store = store("profile-a", "pack-a", "Inventory");
		Pack gear = new Pack();
		gear.id = "gear-a";
		gear.name = "Wear kit";
		gear.type = PackType.EQUIPMENT;
		store.packs.add(gear);
		store.composition.mainPackId = "pack-a";
		store.composition.equipmentPackId = "gear-a";
		repository.save(store);

		PackStore loaded = repository.load("profile-a");
		assertEquals("pack-a", loaded.composition.mainPackId);
		assertEquals("gear-a", loaded.composition.equipmentPackId);
		assertEquals(PackType.EQUIPMENT, loaded.packs.get(1).type);
	}

	@Test
	public void schemaMigrationCreatesBackupBeforeWritingCurrentSchema() throws Exception
	{
		PackStore legacy = store("profile-a", "legacy", "Legacy");
		legacy.schemaVersion = 1;
		legacy.composition = null;
		Path file = repository.profileFile("profile-a");
		Files.write(file, gson.toJson(legacy).getBytes(StandardCharsets.UTF_8));

		PackStore loaded = repository.load("profile-a");
		assertEquals(PackStore.CURRENT_SCHEMA_VERSION, loaded.schemaVersion);
		assertNotNull(loaded.composition);
		assertTrue(hasBackup("backup-v1"));
		assertTrue(new String(Files.readAllBytes(file), StandardCharsets.UTF_8).contains("\"schemaVersion\": 5"));
	}

	@Test
	public void malformedDataIsBackedUpAndRecoversToEmptyStore() throws Exception
	{
		Path file = repository.profileFile("broken-profile");
		Files.write(file, "{ definitely not valid JSON".getBytes(StandardCharsets.UTF_8));

		PackStore recovered = repository.load("broken-profile");
		assertTrue(recovered.packs.isEmpty());
		assertEquals("broken-profile", recovered.profileKey);
		assertTrue(hasBackup("malformed"));
	}

	@Test
	public void profilesUseSeparateFilesAndNeverLeakPacks() throws Exception
	{
		repository.save(store("account-1", "one", "One"));
		repository.save(store("account-2", "two", "Two"));

		PackStore first = repository.load("account-1");
		PackStore second = repository.load("account-2");
		assertEquals("One", first.packs.get(0).name);
		assertEquals("Two", second.packs.get(0).name);
		assertNotEquals(repository.profileFile("account-1"), repository.profileFile("account-2"));
	}

	@Test
	public void encodedImportPreviewsAndRemapsCollidingPackAndParentIds()
	{
		PackStore existing = store("profile-a", "shared-id", "Existing");
		PackStore imported = store("other", "shared-id", "Imported base");
		Pack child = new Pack();
		child.id = "child";
		child.name = "Imported child";
		child.basePackId = "shared-id";
		imported.packs.add(child);

		ImportPreview preview = repository.previewImport(repository.exportEncoded(imported), existing);
		assertEquals(2, preview.packCount);
		assertEquals(1, preview.idCollisionCount);
		PackStore merged = repository.merge(existing, preview, false);
		assertEquals(3, merged.packs.size());
		Pack importedBase = merged.packs.stream().filter(pack -> "Imported base".equals(pack.name)).findFirst().orElse(null);
		Pack importedChild = merged.packs.stream().filter(pack -> "Imported child".equals(pack.name)).findFirst().orElse(null);
		assertNotNull(importedBase);
		assertNotNull(importedChild);
		assertNotEquals("shared-id", importedBase.id);
		assertEquals(importedBase.id, importedChild.basePackId);
		assertFalse(importedBase.id.equals(existing.packs.get(0).id));
	}

	@Test
	public void malformedImportUsesUserFacingError()
	{
		try
		{
			repository.previewImport("not json", new PackStore());
			fail("Malformed import should fail");
		}
		catch (IllegalArgumentException exception)
		{
			assertEquals("Import is not valid PackCheck JSON", exception.getMessage());
		}
	}

	private boolean hasBackup(String marker) throws Exception
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.anyMatch(path -> path.getFileName().toString().contains(marker));
		}
	}

	private PackStore store(String profile, String packId, String packName)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.id = "requirement-a";
		requirement.displayName = "Cape";
		requirement.alternatives.add(MatchOption.exact(6570, "Fire cape"));
		Pack pack = new Pack();
		pack.id = packId;
		pack.name = packName;
		pack.requirements.add(requirement);
		PackStore store = new PackStore();
		store.profileKey = profile;
		store.packs.add(pack);
		return store;
	}
}

package com.packcheck.service;

import com.packcheck.model.MatchOption;
import com.packcheck.model.Pack;
import com.packcheck.model.PackComposition;
import com.packcheck.model.PackRequirement;
import com.packcheck.model.PackResolution;
import com.packcheck.model.PackType;
import com.packcheck.model.ResolvedRequirement;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class PackResolverTest
{
	private final PackResolver resolver = new PackResolver();

	@Test
	public void baseAndMultiLevelInheritanceRemainLiveAndDeterministic()
	{
		Pack general = pack("general", "General", requirement("teleport", "Emergency teleport", 100));
		Pack slayer = pack("slayer", "Slayer", requirement("food", "Food", 101));
		slayer.basePackId = general.id;
		Pack task = pack("task", "Task", requirement("mask", "Face mask", 102));
		task.basePackId = slayer.id;

		List<ResolvedRequirement> resolved = resolver.resolveSingle(task.id, Arrays.asList(task, general, slayer));
		assertEquals(Arrays.asList("teleport", "food", "mask"), Arrays.asList(
			resolved.get(0).requirement.id, resolved.get(1).requirement.id, resolved.get(2).requirement.id));
		assertTrue(resolved.get(0).inherited);
		assertEquals("General", resolved.get(0).sourcePackName);
		assertFalse(resolved.get(2).inherited);
	}

	@Test
	public void tripCompositionCombinesInventoryPackWithSeparateWearKit()
	{
		Pack inventory = pack("inventory", "ToA inventory", requirement("restore", "Restores", 400));
		Pack equipment = pack("equipment", "My ranged kit", requirement("cape", "Cape", 401));
		equipment.type = PackType.EQUIPMENT;
		PackComposition composition = new PackComposition();
		composition.mainPackId = inventory.id;
		composition.equipmentPackId = equipment.id;

		PackResolution resolution = resolver.resolve(composition, Arrays.asList(inventory, equipment));
		assertEquals(2, resolution.requirements.size());
		assertEquals("ToA inventory + My ranged kit", resolution.displayName);
		assertTrue(resolution.conflicts.isEmpty());
	}

	@Test
	public void wearKitsCannotMasqueradeAsInventoryPacksOrAddOns()
	{
		Pack equipment = pack("equipment", "My gear", requirement("cape", "Cape", 401));
		equipment.type = PackType.EQUIPMENT;
		PackComposition composition = new PackComposition();
		composition.mainPackId = equipment.id;
		try
		{
			resolver.resolve(composition, Collections.singletonList(equipment));
			fail("Wear kit should not resolve as the main inventory pack");
		}
		catch (IllegalArgumentException exception)
		{
			assertTrue(exception.getMessage().contains("Wear kit"));
		}

		Pack inventory = pack("inventory", "Inventory");
		equipment.addOnEligible = true;
		composition.mainPackId = inventory.id;
		composition.addOnPackIds.add(equipment.id);
		try
		{
			resolver.resolve(composition, Arrays.asList(inventory, equipment));
			fail("Wear kit should not resolve as an add-on");
		}
		catch (IllegalArgumentException exception)
		{
			assertTrue(exception.getMessage().contains("reusable add-on"));
		}
	}

	@Test
	public void childOverrideAndDisabledInheritedRequirementKeepStableId()
	{
		Pack base = pack("base", "Base", requirement("shared", "Coins", 200));
		PackRequirement override = requirement("shared", "No coins for this child", 200);
		override.enabled = false;
		Pack child = pack("child", "Child", override);
		child.basePackId = base.id;

		List<ResolvedRequirement> resolved = resolver.resolveSingle(child.id, Arrays.asList(base, child));
		assertEquals(1, resolved.size());
		assertEquals("shared", resolved.get(0).requirement.id);
		assertFalse(resolved.get(0).requirement.enabled);
		assertEquals("Child", resolved.get(0).sourcePackName);
	}

	@Test
	public void addOnCompositionMergesUniqueRulesAndRequiresExplicitConflictChoice()
	{
		Pack main = pack("main", "Jad", requirement("cape", "Fire cape", 300));
		Pack addOn = pack("ranged", "Ranged", requirement("bolts", "Bolts", 301));
		addOn.addOnEligible = true;
		PackComposition composition = new PackComposition();
		composition.mainPackId = main.id;
		composition.addOnPackIds.add(addOn.id);
		PackResolution merged = resolver.resolve(composition, Arrays.asList(main, addOn));
		assertEquals(2, merged.requirements.size());
		assertTrue(merged.conflicts.isEmpty());

		Pack conflicting = pack("strict", "Strict ranged", requirement("cape", "Different cape", 302));
		conflicting.addOnEligible = true;
		composition.addOnPackIds = Collections.singletonList(conflicting.id);
		PackResolution unresolved = resolver.resolve(composition, Arrays.asList(main, conflicting));
		assertEquals(1, unresolved.conflicts.size());
		assertEquals("cape", unresolved.conflicts.get(0).requirementId);

		composition.conflictResolutions.put("cape", conflicting.id);
		PackResolution chosen = resolver.resolve(composition, Arrays.asList(main, conflicting));
		assertTrue(chosen.conflicts.isEmpty());
		assertEquals("Different cape", chosen.requirements.get(0).requirement.displayName);
		assertEquals("Strict ranged", chosen.requirements.get(0).sourcePackName);
	}

	@Test
	public void inheritanceCycleIsRejectedWithPath()
	{
		Pack first = pack("first", "First");
		Pack second = pack("second", "Second");
		Pack third = pack("third", "Third");
		first.basePackId = second.id;
		second.basePackId = third.id;
		third.basePackId = first.id;
		try
		{
			resolver.validateNoCycles(Arrays.asList(first, second, third));
			fail("Expected inheritance cycle rejection");
		}
		catch (IllegalArgumentException exception)
		{
			assertTrue(exception.getMessage().contains("first -> second -> third -> first"));
		}
	}

	private Pack pack(String id, String name, PackRequirement... requirements)
	{
		Pack pack = new Pack();
		pack.id = id;
		pack.name = name;
		pack.requirements.addAll(Arrays.asList(requirements));
		return pack;
	}

	private PackRequirement requirement(String id, String name, int itemId)
	{
		PackRequirement requirement = new PackRequirement();
		requirement.id = id;
		requirement.displayName = name;
		requirement.alternatives.add(MatchOption.exact(itemId, name));
		return requirement;
	}
}

